                        <span className="px-3 py-1 bg-gradient-to-r from-success-100 to-success-100 dark:from-success-900/30 dark:to-success-900/30 text-success-700 dark:text-success-600 rounded-full text-sm font-semibold">
                          {(score * 100).toFixed(1)}%
                        </span>
                        {showDetails[`peptide-${idx}`] ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                      </div>
                    </button>

                    {showDetails[`peptide-${idx}`] && (
                      <div className="px-4 pb-4 pt-2 bg-neutral-50 dark:bg-neutral-800/50 border-t border-neutral-200 dark:border-neutral-700">
                        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                          <div>
                            <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">分子量</span>
                            <div className="font-semibold">{('molecular_weight' in peptide ? peptide.molecular_weight : 0).toFixed(1)} Da</div>
                          </div>
                          <div>
                            <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">LogP</span>
                            <div className="font-semibold">{('logp' in peptide ? peptide.logp : 0).toFixed(2)}</div>
                          </div>
                          <div>
                            <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">TPSA</span>
                            <div className="font-semibold">{('tpsa' in peptide ? peptide.tpsa : 0).toFixed(1)} Å²</div>
                          </div>
                          <div>
                            <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">长度</span>
                            <div className="font-semibold">{seq.length} AA</div>
                          </div>
                        </div>
                        {'activity_scores' in peptide && Object.keys(peptide.activity_scores).length > 0 && (
                          <div className="mt-3 pt-3 border-t border-neutral-200 dark:border-neutral-600">
                            <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-2">活性预测</div>
                            <div className="flex flex-wrap gap-2">
                              {Object.entries(peptide.activity_scores).map(([key, val]: [string, number]) => (
                                <span key={key} className="px-2 py-1 bg-secondary-100 dark:bg-secondary-300/25 text-secondary-700 dark:text-secondary-700 rounded text-xs">
                                  {key}: {(val * 100).toFixed(1)}%
                                </span>
                              ))}
                            </div>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                )
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

/**
 * DeepSeek API 密钥配置面板 v2.0 (Enterprise Edition)
 *
 * 功能特性：
 * - 企业级安全存储（AES-256-GCM 加密）
 * - 实时表单验证与强度检测
 * - 可视化配置状态指示
 * - 一键测试连接功能
 * - 完整的错误处理和用户引导
 */

import { useState, useEffect, useCallback } from 'react'
import {
  Card,
  Input,
  Button,
  Alert,
  Badge,
} from '@/components/ui'
import {
  Shield,
  Eye,
  EyeOff,
  CheckCircle,
  XCircle,
  AlertTriangle,
  Loader2,
  RefreshCw,
  Copy,
  Trash2,
  Lock,
  Key,
  Zap,
  Info,
} from 'lucide-react'
import { secureApiKeyManager, type ApiKeyMetadata } from '@/utils/secureKeyManager'
import { unifiedApiKeyManager } from '@/utils/unifiedApiKeyManager'
import { ConfigManager } from '@/utils/configManager'
import { logger } from '@/utils/safeLogger'

// ══════════════════════════════════════
// 类型定义
// ══════════════════════════════════════

interface ApiKeyConfigPanelProps {
  className?: string
  onConfigSuccess?: (metadata: ApiKeyMetadata) => void
  onConfigError?: (error: string) => void
  showTestButton?: boolean
}

type ConfigStatus = 'idle' | 'validating' | 'saving' | 'testing' | 'success' | 'error'

// ══════════════════════════════════════
// 主组件
// ══════════════════════════════════════

export function ApiKeyConfigPanel({
  className,
  onConfigSuccess,
  onConfigError,
  showTestButton = true,
}: ApiKeyConfigPanelProps) {
  // 状态管理
  const [apiKey, setApiKey] = useState('')
  const [showApiKey, setShowApiKey] = useState(false)
  const [status, setStatus] = useState<ConfigStatus>('idle')
  const [message, setMessage] = useState('')
  const [validationResult, setValidationResult] = useState<{
    isValid: boolean
    error?: string
    warning?: string
    strength: 'weak' | 'medium' | 'strong'
  } | null>(null)

  // 配置状态
  const [isConfigured, setIsConfigured] = useState(false)
  const [configInfo, setConfigInfo] = useState<{
    maskedKey: string
    provider: string
    configuredAt: string
  } | null>(null)

  // 初始化：检查现有配置
  useEffect(() => {
    // eslint-disable-next-line react-hooks/immutability
    checkExistingConfig()
  }, [])

  /**
   * 检查是否已有配置
   */
  // eslint-disable-next-line react-hooks/preserve-manual-memoization
  const checkExistingConfig = useCallback(() => {
    try {
      const summary = secureApiKeyManager.getStatusSummary()
      setIsConfigured(summary.configured)

      if (summary.configured) {
        setConfigInfo({
          maskedKey: summary.maskedKey,
          provider: summary.provider,
          configuredAt: summary.configuredAt,
        })
        logger.info('检测到已有的 API Key 配置')
      }
    } catch (error) {
      logger.error('检查配置失败:', error)
    }
  }, [])

  /**
   * 实时验证输入
   */
  const handleInputChange = useCallback((value: string) => {
    setApiKey(value)

    if (!value || value.trim() === '') {
      setValidationResult(null)
      return
    }

    // 实时验证
    const result = secureApiKeyManager.validateApiKey(value)
    setValidationResult(result)

    // 如果之前有错误状态，清除它
    if (status === 'error') {
      setStatus('idle')
      setMessage('')
    }
  }, [status])

  /**
   * 处理提交
   */
  const handleSubmit = useCallback(async () => {
    // 前端验证
    const validation = secureApiKeyManager.validateApiKey(apiKey)

    if (!validation.isValid) {
      setStatus('error')
      setMessage(validation.error || 'API Key 格式无效')
      onConfigError?.(validation.error || '验证失败')
      return
    }

    // 开始保存
    setStatus('saving')
    setMessage('正在安全存储并同步...')

    try {
      // 使用统一管理器同步到两个存储位置 (安全存储 + 传统存储)
      const syncResults = await unifiedApiKeyManager.syncToAll(apiKey, 'deepseek')

      // 检查是否至少有一个成功
      const hasSuccess = syncResults.some(r => r.success)

      if (hasSuccess) {
        setStatus('success')
        const successMessages = syncResults
          .filter(r => r.success)
          .map(r => r.message)
          .join('; ')

        setMessage(`✅ ${successMessages}`)

        // 更新状态显示
        checkExistingConfig()

        // 回调通知
        const metadata = secureApiKeyManager.getMetadata()
        onConfigSuccess?.(metadata!)

        logger.info('API Key 配置并同步成功', syncResults)

        // 3秒后切换到已配置视图
        setTimeout(() => {
          setStatus('idle')
          setMessage('')
        }, 3000)
      } else {
        throw new Error(syncResults.map(r => r.message).join('; '))
      }

    } catch (error) {
      setStatus('error')
      const errorMsg = error instanceof Error ? error.message : '未知错误'
      setMessage(`❌ 配置失败: ${errorMsg}`)
      onConfigError?.(errorMsg)
      logger.error('API Key 配置失败:', error)
    }
  }, [apiKey, checkExistingConfig, onConfigSuccess, onConfigError])

  /**
   * 测试 API 连接
   */
  const handleTestConnection = useCallback(async () => {
    if (!isConfigured) {
      setStatus('error')
      setMessage('请先配置 API Key')
      return
    }

    setStatus('testing')
    setMessage('正在测试连接到 DeepSeek API...')

    try {
      // 从安全存储获取密钥
      const storedKey = await secureApiKeyManager.getApiKey()

      if (!storedKey) {
        throw new Error('无法读取已存储的 API Key')
      }

      // 调用后端测试接口（D-3 收敛：改用不写库的验活端点，避免误写全局配置）
      const testResult = await ConfigManager.testUserLlmKey({
        provider: 'deepseek',
        apiKey: storedKey,
        baseUrl: 'https://api.deepseek.com/v1',
        model: 'deepseek-chat',
      })

      if (testResult.success) {
        setStatus('success')
        setMessage(`🎉 连接测试成功！模型: deepseek-chat`)

        setTimeout(() => {
          setStatus('idle')
          setMessage('')
        }, 3000)
      } else {
        throw new Error(testResult.detail || '验活失败')
      }

    } catch (error) {
      setStatus('error')
      const errorMsg = error instanceof Error ? error.message : '连接测试失败'
      setMessage(`❌ 连接失败: ${errorMsg}`)
      logger.error('API 连接测试失败:', error)
    }
  }, [isConfigured])

  /**
   * 重置/删除配置
   */
  const handleReset = useCallback(() => {
    if (!window.confirm('确定要删除当前 API Key 配置吗？删除后将无法使用 AI 功能。')) {
      return
    }

    const success = secureApiKeyManager.removeApiKey()

    if (success) {
      setApiKey('')
      setIsConfigured(false)
      setConfigInfo(null)
      setValidationResult(null)
      setStatus('idle')
      setMessage('⚠️ API Key 已删除，请重新配置')

      setTimeout(() => {
        setStatus('idle')
        setMessage('')
      }, 2000)
    } else {
      setStatus('error')
      setMessage('❌ 删除失败')
    }
  }, [])

  /**
   * 复制提示信息
   */
  const copyToClipboard = useCallback((text: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setMessage('✅ 已复制到剪贴板')
      setTimeout(() => setMessage(''), 2000)
    })
  }, [])

  // ══════════════════════════════════════
  // 渲染部分
  // ══════════════════════════════════════

  return (
    <Card className={`p-6 ${className || ''}`}>
      {/* 标题区域 */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h2 className="text-lg font-semibold flex items-center gap-2">
            <Shield className="w-5 h-5 text-primary-500" />
            DeepSeek API 密钥配置
          </h2>
          <p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">
            安全配置你的 API 密钥以启用 AI 智能对话功能
          </p>
        </div>

        {isConfigured && (
          <Badge variant="success" className="flex items-center gap-1">
            <CheckCircle className="w-3 h-3" />
            已配置
          </Badge>
        )}
      </div>

      {/* 状态消息 */}
      {message && (
        <Alert
          variant={
            status === 'success' ? 'success' :
            status === 'error' ? 'destructive' :
            'default'
          }
          className="mb-4"
        >
          {status === 'success' && <CheckCircle className="w-4 h-4" />}
          {status === 'error' && <XCircle className="w-4 h-4" />}
          {(status === 'saving' || status === 'testing') && <Loader2 className="w-4 h-4 animate-spin" />}
          <span>{message}</span>
        </Alert>
      )}

      {/* 已配置状态视图 */}
      {isConfigured && !apiKey ? (
        <div className="space-y-4">
          {/* 配置信息卡片 */}
          <div className="p-4 rounded-lg bg-success-50 dark:bg-success-300/15 border border-success-200 dark:border-success-800/40">
            <div className="flex items-start justify-between">
              <div className="space-y-2 flex-1">
                <div className="flex items-center gap-2">
                  <Lock className="w-4 h-4 text-success-600" />
                  <span className="font-medium text-success-700 dark:text-success-600">
                    API Key 已安全存储
                  </span>
                </div>

                <div className="text-sm space-y-1">
                  <p className="text-neutral-600 dark:text-neutral-400">
                    <span className="font-medium">脱敏显示：</span>
                    <code className="ml-2 px-2 py-1 bg-white dark:bg-neutral-800 rounded text-xs">
                      {configInfo?.maskedKey}
                    </code>
                    <button
                      onClick={() => copyToClipboard(configInfo?.maskedKey || '')}
                      className="ml-2 text-primary-500 hover:text-primary-700"
                    >
                      <Copy className="w-3 h-3 inline" />
                    </button>
                  </p>

                  <p className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] text-xs">
                    <span>提供商：</span>{configInfo?.provider || 'deepseek'}
                    {' • '}
                    <span>配置时间：</span>
                    {configInfo?.configuredAt ? new Date(configInfo.configuredAt).toLocaleString('zh-CN') : '未知'}
                  </p>
                </div>
              </div>

              <div className="flex items-start gap-2 ml-4">
                {showTestButton && (
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={handleTestConnection}
                    loading={status === 'testing'}
                    icon={<Zap className="w-4 h-4" />}
                  >
                    测试连接
                  </Button>
                )}

                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => {
                    setIsConfigured(false)
                    setApiKey('')
                  }}
                  icon={<RefreshCw className="w-4 h-4" />}
                >
                  更新
                </Button>

                <Button
                  size="sm"
                  variant="ghost"
                  onClick={handleReset}
                  icon={<Trash2 className="w-4 h-4 text-danger-500" />}
                >
                  删除
                </Button>
              </div>
            </div>
          </div>

          {/* 安全说明 */}
          <div className="flex items-start gap-2 p-3 rounded-lg bg-secondary-50 dark:bg-secondary-300/15 border border-secondary-200 dark:border-secondary-800/40">
            <Info className="w-4 h-4 text-secondary-500 mt-0.5 flex-shrink-0" />
            <div className="text-sm text-secondary-700 dark:text-secondary-700">
              <p className="font-medium">安全提示</p>
              <ul className="mt-1 space-y-1 text-xs list-disc list-inside">
                <li>API Key 使用 AES-256-GCM 军事级加密存储在本地浏览器中</li>
                <li>密钥不会明文传输或暴露在网络请求日志中</li>
                <li>每次使用时动态解密，用完立即从内存清除</li>
              </ul>
            </div>
          </div>
        </div>
      ) : (
        /* 输入表单 */
        <div className="space-y-4">
          {/* API Key 输入框 */}
          <div className="space-y-2">
            <label className="text-sm font-medium text-neutral-700 dark:text-neutral-300 flex items-center gap-1">
              <Key className="w-4 h-4" />
              API 密钥
              <span className="text-danger-500">*</span>
            </label>

            <div className="relative">
              <Input
                type={showApiKey ? "text" : "password"}
                value={apiKey}
                onChange={(e) => handleInputChange(e.target.value)}
                placeholder="sk-xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx (通常50+字符)"
                className={`pr-20 ${
                  validationResult?.isValid === false ? 'border-danger-300 focus:border-danger-500' :
                  validationResult?.isValid === true ? 'border-success-300 focus:border-success-500' :
                  ''
                }`}
                disabled={status === 'saving' || status === 'testing'}
                autoFocus
              />

              {/* 显示/隐藏按钮 */}
              <button
                type="button"
                className="absolute right-12 top-1/2 -translate-y-1/2 p-1 text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-300"
                onClick={() => setShowApiKey(!showApiKey)}
                tabIndex={-1}
              >
                {showApiKey ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
              </button>

              {/* 强度指示器 */}
              {validationResult?.isValid && (
                <div className="absolute right-2 top-1/2 -translate-y-1/2">
                  <Badge
                    variant={
                      validationResult.strength === 'strong' ? 'success' :
                      validationResult.strength === 'medium' ? 'warning' :
                      'danger'
                    }
                    className="text-xs"
                  >
                    {validationResult.strength === 'strong' ? '强' :
                     validationResult.strength === 'medium' ? '中' : '弱'}
                  </Badge>
                </div>
              )}
            </div>

            {/* 验证反馈 */}
            {validationResult && (
              <div className={`text-xs flex items-center gap-1 ${
                validationResult.isValid === false ? 'text-danger-600' :
                validationResult.warning ? 'text-warning-600' :
                'text-success-600'
              }`}>
                {validationResult.isValid === false && <XCircle className="w-3 h-3" />}
                {validationResult.isValid === true && !validationResult.warning && <CheckCircle className="w-3 h-3" />}
                {validationResult.warning && <AlertTriangle className="w-3 h-3" />}
                <span>
                  {validationResult.error ||
                   validationResult.warning ||
                   (validationResult.isValid ? '格式正确 ✓' : '')}
                </span>
              </div>
            )}
          </div>

          {/* 提交按钮组 */}
          <div className="flex gap-3 pt-2">
            <Button
              onClick={handleSubmit}
              disabled={!apiKey.trim() || !validationResult?.isValid || status === 'saving' || status === 'testing'}
              loading={status === 'saving'}
              icon={<Shield className="w-4 h-4" />}
              className="flex-1"
            >
              {status === 'saving' ? '正在加密保存...' : '安全保存配置'}
            </Button>

            {isConfigured && (
              <Button
                variant="ghost"
                onClick={() => {
                  setApiKey('')
                  setIsConfigured(true)
                }}
              >
                取消
              </Button>
            )}
          </div>

          {/* 帮助信息 */}
          <div className="pt-2 border-t border-neutral-200 dark:border-neutral-700">
            {/* 交叉引导文案 */}
            <div className="mb-3 p-3 rounded-lg bg-secondary-50 dark:bg-secondary-300/15 border border-secondary-200 dark:border-secondary-800/40">
              <p className="text-xs text-secondary-700 dark:text-secondary-700 font-medium mb-1">
                💡 这是<strong>快速配置</strong>入口（推荐大多数用户使用）
              </p>
              <ul className="text-xs text-secondary-600 dark:text-secondary-700 space-y-1 list-disc list-inside">
                <li>✅ 适合首次配置或只想快速开始使用的用户</li>
                <li>✅ 使用 AES-256-GCM 军事级加密保护</li>
                <li>✅ 配置会自动同步到系统所有模块</li>
              </ul>
              <p className="text-xs text-secondary-500 dark:text-secondary-700 mt-2">
                📌 如需管理多个模型或调整高级参数（temperature/timeout等），
                请前往页面顶部的<strong>"配置管理"</strong>标签页。
              </p>
            </div>

            <details className="group">
              <summary className="text-xs text-neutral-500 cursor-pointer hover:text-neutral-700 dark:hover:text-neutral-300">
                如何获取 DeepSeek API Key？
              </summary>

              <div className="mt-2 p-3 rounded-lg bg-neutral-50 dark:bg-neutral-800/50 text-xs space-y-2">
                <ol className="list-decimal list-inside space-y-1 text-neutral-600 dark:text-neutral-400">
                  <li>访问 <a href="https://platform.deepseek.com/" target="_blank" rel="noopener noreferrer" className="text-primary-500 hover:underline">DeepSeek 开放平台</a></li>
                  <li>注册/登录账号</li>
                  <li>进入左侧菜单 <strong>"API Keys"</strong></li>
                  <li>点击 <strong>"Create API Key"</strong></li>
                  <li>复制完整的 API Key（以 sk- 开头）</li>
                  <li>粘贴到上方输入框并点击保存</li>
                </ol>

                <p className="text-warning-600 dark:text-warning-700 mt-2">
                  ⚠️ 请确保账户余额充足，API 调用可能产生费用
                </p>
              </div>
            </details>
          </div>
        </div>
      )}
    </Card>
  )
}

export default ApiKeyConfigPanel

/**
 * API Key 诊断工具 v7.1
 *
 * 用于快速定位和解决 401 Unauthorized 认证失败问题
 * 功能：
 * - 自动检测当前存储的 API Key
 * - 识别隐藏字符和格式问题
 * - 一键清洗和修复
 * - 实时验证 Key 有效性
 * - 详细的诊断报告生成
 */
import { useState, useEffect } from 'react'
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  Button,
  Badge,
  Alert,
  AlertDescription,
} from '@/components/ui'
import {
  CheckCircle2,
  XCircle,
  AlertTriangle,
  RefreshCw,
  Eye,
  EyeOff,
  ClipboardCopy,
  ExternalLink,
  Shield,
  Bug,
  Terminal,
  Zap,
} from 'lucide-react'
import { unifiedApiKeyManager } from '@/utils/unifiedApiKeyManager'
import { logger } from '@/utils/safeLogger'

interface DiagnosticResult {
  timestamp: string
  source: string | null
  rawKey: string
  cleanedKey: string
  keyLength: number
  cleanedLength: number
  hiddenCharsRemoved: number
  isValidFormat: boolean
  issues: string[]
  suggestions: string[]
}

export default function ApiKeyDiagnosticTool() {
  const [diagnostic, setDiagnostic] = useState<DiagnosticResult | null>(null)
  const [loading, setLoading] = useState(false)
  const [showRawKey, setShowRawKey] = useState(false)
  const [testResult, setTestResult] = useState<{
    success: boolean
    message: string
    details?: unknown
  } | null>(null)

  useEffect(() => {
    // eslint-disable-next-line react-hooks/immutability
    runDiagnostic()
  }, [])

  /**
   * 运行完整的 API Key 诊断
   */
  const runDiagnostic = async () => {
    setLoading(true)
    setTestResult(null)

    try {
      // Step 1: 从统一管理器获取 Key
      const keyResult = await unifiedApiKeyManager.getApiKey()
      const rawKey = keyResult.apiKey

      // Step 2: 清洗 Key（移除隐藏字符）
      const cleanedKey = sanitizeKey(rawKey)

      // Step 3: 分析问题
      const issues: string[] = []
      const suggestions: string[] = []

      if (!rawKey) {
        issues.push('❌ 未找到任何 API Key 配置')
        suggestions.push('请在"配置管理" → "LLM" Tab 中输入您的 DeepSeek API Key')
      } else {
        const trimmedKey = rawKey.trim()

        // 检查是否是有效的 DeepSeek API Key 格式
        const isValidDeepSeekKey = /^sk-[a-zA-Z0-9]{20,}$/.test(trimmedKey)

        // 检查长度
        if (trimmedKey.length < 20) {
          issues.push(`⚠️ Key 长度过短：${trimmedKey.length} 字符 (需要 ≥20)`)
          suggestions.push('请确认完整复制了 API Key，通常应为 40-60 字符')
        } else if (trimmedKey.length > 100) {
          issues.push(`⚠️ Key 长度过长：${trimmedKey.length} 字符 (通常 ≤100)`)
          suggestions.push('可能包含了多余的内容，请检查是否完整复制')
        }

        // 检查格式
        if (!trimmedKey.startsWith('sk-') && !trimmedKey.startsWith('Bearer ')) {
          issues.push('⚠️ Key 格式异常：不以 "sk-" 或 "Bearer " 开头')
          suggestions.push('DeepSeek API Key 通常以 "sk-" 开头，请检查是否复制正确')
        }

        // 如果是 sk- 开头，进行更详细的格式验证
        if (trimmedKey.startsWith('sk-')) {
          if (!isValidDeepSeekKey && trimmedKey.length >= 20) {
            issues.push('⚠️ DeepSeek API Key 格式可能不正确')
            suggestions.push('有效的DeepSeek Key应为: sk- + 字母数字组合（无特殊符号）')
          }
        }

        // 检查隐藏字符
        const hiddenCount = rawKey.length - cleanedKey.length
        if (hiddenCount > 0) {
          issues.push(`⚠️ 发现 ${hiddenCount} 个隐藏字符`)
          suggestions.push('点击"清洗并修复"按钮自动移除隐藏字符')
        }

        // 检查常见占位符（仅检测完整的占位符文本，不误判真实API Key）
        const fullPlaceholders = [
          'your-api-key',
          'your-api-key-here',
          'YOUR_API_KEY',
          '<your-api-key>',
          'your_api_key_here',
          'REPLACE_WITH_YOUR_KEY',
          'test',
          'demo',
          'example',
        ]

        const isExactPlaceholder = fullPlaceholders.some(
          p => trimmedKey.toLowerCase() === p.toLowerCase(),
        )

        // 只有当key很短且不是sk-开头时，才判定为可能的占位符
        const isLikelyPlaceholder = trimmedKey.length <= 15 &&
                                   !trimmedKey.startsWith('sk-') &&
                                   !trimmedKey.startsWith('Bearer ')

        if (isExactPlaceholder || isLikelyPlaceholder) {
          issues.push('❌ 检测到占位符文本，不是真实的 API Key')
          suggestions.push('请替换为从 https://platform.deepseek.com/ 获取的真实 API Key')
          suggestions.push('真实API Key通常以"sk-"开头，长度为32-60个字符')
        }

        // 如果没有问题
        if (issues.length === 0) {
          if (isValidDeepSeekKey) {
            suggestions.push('✅ API Key 格式完全符合 DeepSeek 规范')
          } else {
            suggestions.push('✅ API Key 格式看起来正常')
          }
          suggestions.push('如果仍然出现 401 错误，可能是 Key 已过期或账户余额不足')
          suggestions.push('请访问 https://platform.deepseek.com/ 检查您的API Key状态')
        }
      }

      const result: DiagnosticResult = {
        timestamp: new Date().toISOString(),
        source: keyResult.source,
        rawKey,
        cleanedKey,
        keyLength: rawKey.length,
        cleanedLength: cleanedKey.length,
        hiddenCharsRemoved: rawKey.length - cleanedKey.length,
        isValidFormat: issues.filter(i => i.includes('❌')).length === 0,
        issues,
        suggestions,
      }

      setDiagnostic(result)
      logger.info('API Key 诊断完成', result)
    } catch (error) {
      logger.error('API Key 诊断失败:', error)
      setDiagnostic({
        timestamp: new Date().toISOString(),
        source: null,
        rawKey: '',
        cleanedKey: '',
        keyLength: 0,
        cleanedLength: 0,
        hiddenCharsRemoved: 0,
        isValidFormat: false,
        issues: ['❌ 诊断过程发生错误'],
        suggestions: ['请刷新页面重试', '检查浏览器控制台是否有详细错误信息'],
      })
    } finally {
      setLoading(false)
    }
  }

  /**
   * 清洗 API Key（移除隐藏字符）
   */
  const sanitizeKey = (key: string): string => {
    if (!key) return ''

    let cleaned = key.trim()
    cleaned = cleaned.replace(/[\s\r\n\t\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000\uFEFF]/g, '')
    cleaned = cleaned.replace(/[\u200B-\u200D\uFEFF\u2060]/g, '')
    // eslint-disable-next-line no-control-regex
    cleaned = cleaned.replace(/[\x00-\x1F\x7F]/g, '')

    return cleaned
  }

  /**
   * 一键清洗并更新存储
   */
  const handleCleanAndFix = async () => {
    if (!diagnostic?.rawKey) return

    try {
      const cleanedKey = diagnostic.cleanedKey

      if (cleanedKey.length >= 20) {
        // 同步到安全存储
        await unifiedApiKeyManager.syncToAll(cleanedKey, 'deepseek')

        setTestResult({
          success: true,
          message: `✅ 清洗完成！已移除 ${diagnostic.hiddenCharsRemoved} 个隐藏字符，Key 已更新`,
        })

        setTimeout(() => runDiagnostic(), 1000)
      } else {
        setTestResult({
          success: false,
          message: '❌ 清洗后 Key 仍然太短或为空，无法保存',
        })
      }
    } catch (error) {
      setTestResult({
        success: false,
        message: `❌ 更新失败: ${error instanceof Error ? error.message : '未知错误'}`,
      })
    }
  }

  /**
   * 复制到剪贴板
   */
  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setTestResult({ success: true, message: '✅ 已复制到剪贴板' })
      setTimeout(() => setTestResult(null), 2000)
    })
  }

  /**
   * 测试 API 连接
   */
  const testConnection = async () => {
    if (!diagnostic?.cleanedKey) return

    setTestResult({ success: false, message: '🔄 正在测试连接...' })

    try {
      const response = await fetch('/api/v1/ai/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          question: 'test',
          api_key: diagnostic.cleanedKey,
        }),
      })

      if (response.ok) {
        setTestResult({
          success: true,
          message: '✅ 连接成功！API Key 有效',
        })
      } else {
        const errorData = await response.json()
        setTestResult({
          success: false,
          message: `❌ 连接失败 (${response.status}): ${errorData.answer || response.statusText}`,
          details: errorData,
        })
      }
    } catch (error) {
      setTestResult({
        success: false,
        message: `❌ 网络错误: ${error instanceof Error ? error.message : '未知错误'}`,
      })
    }
  }

  if (!diagnostic) {
    return (
      <Card className="w-full">
        <CardContent className="flex items-center justify-center py-12">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
          <span className="ml-3 text-neutral-600">正在分析 API Key...</span>
        </CardContent>
      </Card>
    )
  }

  return (
    <div className="space-y-4">
      {/* 标题栏 */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="text-lg flex items-center gap-2">
              <Bug className="w-5 h-5 text-secondary-600" />
              API Key 诊断工具 v7.1
            </CardTitle>
            <Button variant="outline" size="sm" onClick={runDiagnostic} disabled={loading}>
              <RefreshCw className={`w-4 h-4 mr-2 ${loading ? 'animate-spin' : ''}`} />
              重新诊断
            </Button>
          </div>
        </CardHeader>
      </Card>

      {/* 状态概览 */}
      <Card>
        <CardContent className="pt-6">
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4">
            <div className="p-3 bg-neutral-50 dark:bg-neutral-800 rounded-lg">
              <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">存储来源</p>
              <Badge variant={diagnostic.source === 'none' ? 'danger' : 'neutral'}>
                {diagnostic.source || '未配置'}
              </Badge>
            </div>

            <div className="p-3 bg-neutral-50 dark:bg-neutral-800 rounded-lg">
              <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">原始长度</p>
              <p className="text-lg font-bold">{diagnostic.keyLength} 字符</p>
            </div>

            <div className="p-3 bg-neutral-50 dark:bg-neutral-800 rounded-lg">
              <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">隐藏字符</p>
              <p className={`text-lg font-bold ${diagnostic.hiddenCharsRemoved > 0 ? 'text-error-600' : 'text-success-600'}`}>
                {diagnostic.hiddenCharsRemoved} 个
              </p>
            </div>

            <div className="p-3 bg-neutral-50 dark:bg-neutral-800 rounded-lg">
              <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">格式有效性</p>
              {diagnostic.isValidFormat ? (
                <CheckCircle2 className="w-6 h-6 text-success-600" />
              ) : (
                <XCircle className="w-6 h-6 text-error-600" />
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* API Key 详情 */}
      {diagnostic.rawKey && (
        <Card>
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              <Terminal className="w-4 h-4" />
              API Key 详情
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {/* 原始 Key */}
              <div>
                <label className="text-sm font-medium text-neutral-700 dark:text-neutral-300 flex items-center gap-2">
                  原始值（可能包含隐藏字符）
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => setShowRawKey(!showRawKey)}
                    className="!h-6 !px-2"
                  >
                    {showRawKey ? <EyeOff className="w-3 h-3" /> : <Eye className="w-3 h-3" />}
                  </Button>
                </label>
                <div className="mt-1 p-3 bg-neutral-900 text-success-400 rounded-md font-mono text-sm break-all relative group">
                  {showRawKey ? diagnostic.rawKey : maskKey(diagnostic.rawKey)}
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => copyToClipboard(diagnostic.rawKey)}
                    className="absolute top-2 right-2 !h-7 !px-2 opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <ClipboardCopy className="w-3 h-3" />
                  </Button>
                </div>
              </div>

              {/* 清洗后 Key */}
              {diagnostic.hiddenCharsRemoved > 0 && (
                <div>
                  <label className="text-sm font-medium text-neutral-700 dark:text-neutral-300">
                    清洗后值（已移除隐藏字符）
                  </label>
                  <div className="mt-1 p-3 bg-success-900 text-success-300 rounded-md font-mono text-sm break-all">
                    {maskKey(diagnostic.cleanedKey)}
                  </div>
                </div>
              )}

              {/* 操作按钮 */}
              <div className="flex gap-2 pt-2">
                {diagnostic.hiddenCharsRemoved > 0 && (
                  <Button onClick={handleCleanAndFix} size="sm">
                    <Zap className="w-4 h-4 mr-2" />
                    清洗并修复
                  </Button>
                )}
                <Button
                  variant="outline"
                  onClick={testConnection}
                  size="sm"
                  disabled={!diagnostic.cleanedKey}
                >
                  <Shield className="w-4 h-4 mr-2" />
                  测试连接
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() =>
                    window.open('https://platform.deepseek.com/', '_blank')
                  }
                >
                  <ExternalLink className="w-4 h-4 mr-2" />
                  获取新 Key
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* 问题列表 */}
      {diagnostic.issues.length > 0 && (
        <Alert variant={diagnostic.issues.some(i => i.includes('❌')) ? 'destructive' : 'warning'}>
          <AlertTriangle className="h-4 w-4" />
          <AlertDescription>
            <div className="space-y-1 mt-2">
              <p className="font-semibold">发现的问题：</p>
              {diagnostic.issues.map((issue, idx) => (
                <p key={idx}>{issue}</p>
              ))}
            </div>
          </AlertDescription>
        </Alert>
      )}

      {/* 建议 */}
      <Card>
        <CardContent className="pt-6">
          <h4 className="font-semibold mb-3 flex items-center gap-2">
            💡 建议与解决方案
          </h4>
          <ul className="space-y-2">
            {diagnostic.suggestions.map((suggestion, idx) => (
              <li key={idx} className="text-sm text-neutral-700 dark:text-neutral-300 flex items-start gap-2">
                <span className="text-secondary-500 mt-1">•</span>
                <span>{suggestion}</span>
              </li>
            ))}
          </ul>
        </CardContent>
      </Card>

      {/* 测试结果 */}
      {testResult && (
        <Alert variant={testResult.success ? 'default' : 'destructive'}>
          {testResult.success ? (
            <CheckCircle2 className="h-4 w-4" />
          ) : (
            <XCircle className="h-4 w-4" />
          )}
          <AlertDescription>{testResult.message}</AlertDescription>
        </Alert>
      )}

      {/* 诊断时间戳 */}
      <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] text-right">
        最后诊断时间: {new Date(diagnostic.timestamp).toLocaleString()}
      </p>
    </div>
  )
}

/**
 * 脱敏显示 API Key
 */
function maskKey(key: string): string {
  if (!key || key.length <= 12) return key || '(空)'
  return `${key.substring(0, 8)}...${key.substring(key.length - 4)}`
}

import { useState, useEffect, useRef } from 'react'
import { cn } from '@/lib/utils'
import type { GenerationProgress } from '@/hooks/useGenerationProgress'
import { Loader2, X, CheckCircle2, AlertCircle, Clock } from 'lucide-react'

interface GenerationProgressPanelProps {
  progress: GenerationProgress
  onCancel?: () => void
  showCancelButton?: boolean
  className?: string
}

const STAGE_CONFIG = {
  idle: {
    label: '等待中',
    color: 'bg-neutral-400',
    gradient: 'from-neutral-400 to-neutral-500',
    icon: null,
  },
  preparing: {
    label: '准备中',
    color: 'bg-secondary-500',
    gradient: 'from-secondary-400 to-secondary-600',
    icon: Loader2,
  },
  generating: {
    label: '生成配方',
    color: 'bg-info-500',
    gradient: 'from-info-400 to-info-600',
    icon: Loader2,
  },
  optimizing: {
    label: '优化方案',
    color: 'bg-warning-500',
    gradient: 'from-warning-400 to-warning-600',
    icon: Loader2,
  },
  validating: {
    label: '验证安全',
    color: 'bg-accent-500',
    gradient: 'from-accent-400 to-accent-600',
    icon: Loader2,
  },
  complete: {
    label: '生成完成',
    color: 'bg-success-500',
    gradient: 'from-success-400 to-success-600',
    icon: CheckCircle2,
  },
  error: {
    label: '生成失败',
    color: 'bg-error-500',
    gradient: 'from-error-400 to-error-600',
    icon: AlertCircle,
  },
}

function formatTime(seconds?: number): string {
  if (!seconds) return ''
  if (seconds < 60) return `${Math.round(seconds)}秒`
  const mins = Math.floor(seconds / 60)
  const secs = Math.round(seconds % 60)
  return `${mins}分${secs}秒`
}

export function GenerationProgressPanel({
  progress,
  onCancel,
  showCancelButton = true,
  className,
}: GenerationProgressPanelProps) {
  const config = STAGE_CONFIG[progress.stage]
  const isActive = progress.stage !== 'idle' && progress.stage !== 'complete' && progress.stage !== 'error'
  const [announcement, setAnnouncement] = useState('')
  const cancelButtonRef = useRef<HTMLButtonElement>(null)
  const previousStage = useRef(progress.stage)

  useEffect(() => {
    if (previousStage.current !== progress.stage) {
      if (progress.stage === 'complete') {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        setAnnouncement('配方生成完成')
      } else if (progress.stage === 'error') {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        setAnnouncement('配方生成失败')
      } else if (progress.stage === 'generating') {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        setAnnouncement('正在生成配方')
      }
      previousStage.current = progress.stage
    }
  }, [progress.stage])

  useEffect(() => {
    if (isActive && cancelButtonRef.current) {
      cancelButtonRef.current.focus()
    }
  }, [isActive])

  const handleCancelKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      onCancel?.()
    }
  }

  if (progress.stage === 'idle') {
    return null
  }

  return (
    <div
      className={cn(
        'relative overflow-hidden rounded-xl border bg-white dark:bg-neutral-800 shadow-lg',
        'border-neutral-200 dark:border-neutral-700',
        className,
      )}
      role="region"
      aria-labelledby="progress-panel-title"
    >
      <span id="progress-panel-title" className="sr-only">配方生成进度面板</span>
      <div aria-live="polite" className="sr-only">
        {announcement}
      </div>
      <div className="relative p-4 space-y-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            {config.icon && (
              <div className={cn(
                'w-8 h-8 rounded-full flex items-center justify-center',
                'bg-gradient-to-br ' + config.gradient,
                isActive && 'animate-pulse',
              )}>
                <config.icon className="w-4 h-4 text-white" />
              </div>
            )}
            {!config.icon && progress.stage === 'complete' && (
              <div className="w-8 h-8 rounded-full flex items-center justify-center bg-gradient-to-br from-success-400 to-success-600">
                <CheckCircle2 className="w-4 h-4 text-white" />
              </div>
            )}
            {!config.icon && progress.stage === 'error' && (
              <div className="w-8 h-8 rounded-full flex items-center justify-center bg-gradient-to-br from-error-400 to-error-600">
                <AlertCircle className="w-4 h-4 text-white" />
              </div>
            )}
            <div>
              <span className="font-semibold text-neutral-900 dark:text-neutral-100">
                {config.label}
              </span>
              {progress.message && (
                <span className="ml-2 text-sm text-neutral-500 dark:text-neutral-400">
                  {progress.message}
                </span>
              )}
            </div>
          </div>

          <div className="flex items-center gap-3">
            {progress.estimatedTimeRemaining && isActive && (
              <div className="flex items-center gap-1.5 text-xs text-neutral-500 dark:text-neutral-400">
                <Clock className="w-3.5 h-3.5" />
                <span>约剩余 {formatTime(progress.estimatedTimeRemaining)}</span>
              </div>
            )}

            {progress.canCancel && showCancelButton && onCancel && (
              <button
                ref={cancelButtonRef}
                onClick={onCancel}
                onKeyDown={handleCancelKeyDown}
                className={cn(
                  'flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium',
                  'bg-neutral-100 dark:bg-neutral-700 text-neutral-600 dark:text-neutral-300',
                  'hover:bg-danger-100 dark:hover:bg-danger-900/30 hover:text-danger-600 dark:hover:text-danger-400',
                  'transition-colors duration-200',
                  'focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2',
                )}
                aria-label="取消配方生成"
              >
                <X className="w-3.5 h-3.5" />
                取消
              </button>
            )}
          </div>
        </div>

        <div className="relative">
          <div
            className="h-3 bg-neutral-100 dark:bg-neutral-700 rounded-full overflow-hidden"
            role="progressbar"
            aria-valuenow={progress.progress}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-label={`配方生成进度: ${progress.progress}%`}
          >
            <div
              className={cn(
                'h-full rounded-full transition-all duration-500 ease-out',
                'bg-gradient-to-r ' + config.gradient,
                isActive && 'animate-pulse',
              )}
              style={{ width: `${progress.progress}%` }}
            />
          </div>

          <div className="flex justify-between text-xs text-neutral-500 dark:text-neutral-400">
            <span>{progress.message}</span>
            <span className="font-medium text-primary-700 dark:text-primary-700">{progress.progress}%</span>
          </div>

          <div className="flex justify-between mt-1.5">
            <span className="text-xs text-neutral-500 dark:text-neutral-400">
              {progress.progress < 100 ? `${progress.progress}%` : '100%'}
            </span>
            <div className="flex gap-1">
              {['preparing', 'generating', 'optimizing', 'validating'].map((stage) => {
                const stageProgress = {
                  preparing: 10,
                  generating: 40,
                  optimizing: 70,
                  validating: 90,
                }[stage]!
                const isComplete = progress.progress >= stageProgress
                const isCurrent = progress.stage === stage
                const dotColorClass = isComplete
                  ? isCurrent
                    ? config.color
                    : 'bg-neutral-400'
                  : 'bg-neutral-300 dark:bg-neutral-600'
                return (
                  <div
                    key={stage}
                    className={cn(
                      'w-1.5 h-1.5 rounded-full transition-all duration-300',
                      dotColorClass,
                    )}
                  />
                )
              })}
            </div>
          </div>
        </div>

        {progress.stage === 'complete' && (
          <div className="flex items-center gap-2 text-sm text-success-600 dark:text-success-600">
            <CheckCircle2 className="w-4 h-4" />
            <span>{progress.message || '配方生成成功'}</span>
          </div>
        )}

        {progress.stage === 'error' && (
          <div className="flex items-center gap-2 text-sm text-error-600 dark:text-error-600">
            <AlertCircle className="w-4 h-4" />
            <span>{progress.message || '生成失败，请重试'}</span>
          </div>
        )}
      </div>
    </div>
  )
}

import { Card, Badge, Button } from '@/components/ui';
import { Brain, TrendingUp, TrendingDown, Minus, AlertTriangle, CheckCircle, ArrowUpDown } from 'lucide-react';
import type { AICandidate } from '@/api/ai';

interface MultiCandidateCompareProps {
  candidates: AICandidate[];
  onSelectCandidate?: (candidate: AICandidate) => void;
  selectedIndex?: number;
}

interface CompareResult {
  dimension: string;
  values: number[];
  bestIndex: number;
  differences: ('up' | 'down' | 'same')[];
}

export function MultiCandidateCompare({ candidates, onSelectCandidate, selectedIndex }: MultiCandidateCompareProps) {
  if (!candidates || candidates.length < 2) {
    return (
      <Card className="p-6 text-center text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
        <p className="text-sm">需要至少2个候选方案才能进行对比分析</p>
      </Card>
    );
  }

  const scoreDimensions: { key: keyof AICandidate; label: string; format?: (v: any) => string }[] = [
    { key: 'overall_score', label: '综合评分', format: (v) => (v != null ? (v as number).toFixed(3) : '-') },
    { key: 'synergy_score', label: '协同评分', format: (v) => (v != null ? (v as number).toFixed(3) : '-') },
    { key: 'taste_score', label: '口感评分', format: (v) => (v != null ? (v as number).toFixed(3) : '-') },
    { key: 'stability_score', label: '稳定性', format: (v) => (v != null ? (v as number).toFixed(3) : '-') },
  ];

  const safetyOk = candidates.map((c) => c.safety_passed);
  const herbCounts = candidates.map((c) => c.herb_combination?.length ?? 0);
  const peptideCounts = candidates.map((c) => c.peptide_candidates?.length || 0);

  const compareValues = (values: number[]): CompareResult => {
    const bestIndex = values.reduce((bestIdx, val, idx, arr) => (val > arr[bestIdx] ? idx : bestIdx), 0);
    const differences = values.map((v) => (v > values[bestIndex] ? 'down' : v < values[bestIndex] ? 'up' : 'same'));
    return {
      dimension: '',
      values,
      bestIndex,
      differences,
    };
  };

  const overallScores = candidates.map((c) => c.overall_score ?? 0);
  const synergyScores = candidates.map((c) => c.synergy_score ?? 0);
  const tasteScores = candidates.map((c) => c.taste_score ?? 0);
  const stabilityScores = candidates.map((c) => c.stability_score ?? 0);

  const overallCompare = compareValues(overallScores);
  const synergyCompare = compareValues(synergyScores);
  const tasteCompare = compareValues(tasteScores);
  const stabilityCompare = compareValues(stabilityScores);

  const getDifferenceIcon = (diff: 'up' | 'down' | 'same') => {
    switch (diff) {
      case 'up':
        return <TrendingUp className="w-3 h-3 text-danger-500" />;
      case 'down':
        return <TrendingDown className="w-3 h-3 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />;
      default:
        return <Minus className="w-3 h-3 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />;
    }
  };

  const getCellClass = (diff: 'up' | 'down' | 'same', isBest: boolean) => {
    const baseClass = 'text-center px-3 py-2 text-sm';
    if (isBest && diff === 'same') {
      return `${baseClass} bg-success-50/50 dark:bg-success-300/20 font-semibold text-success-600`;
    }
    if (diff === 'up') {
      return `${baseClass} bg-danger-50/30 dark:bg-danger-300/15 text-danger-600 dark:text-danger-600`;
    }
    if (diff === 'down') {
      return `${baseClass} text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]`;
    }
    return `${baseClass} text-neutral-600 dark:text-neutral-400`;
  };

  const getHerbRoleSet = (candidate: AICandidate) => {
    const roles: Record<string, Set<string>> = { 君: new Set(), 臣: new Set(), 佐: new Set(), 使: new Set() };
    candidate.herb_combination?.forEach((h) => {
      const role = typeof h.role === 'string' ? h.role : '';
      const name = typeof h.name === 'string' ? h.name : '未知药材';
      if (/君/i.test(role)) roles['君'].add(name);
      else if (/臣/i.test(role)) roles['臣'].add(name);
      else if (/佐/i.test(role)) roles['佐'].add(name);
      else if (/使/i.test(role)) roles['使'].add(name);
    });
    return roles;
  };

  const candidate1Roles = getHerbRoleSet(candidates[0]);
  const candidate2Roles = getHerbRoleSet(candidates[1]);

  const getRoleDifferences = () => {
    const diffs: { type: 'added' | 'removed' | 'changed'; herb?: string; role?: string; text: string }[] = [];
    ['君', '臣', '佐', '使'].forEach((role) => {
      const set1 =
        role === '君'
          ? candidate1Roles['君']
          : role === '臣'
            ? candidate1Roles['臣']
            : role === '佐'
              ? candidate1Roles['佐']
              : candidate1Roles['使'];
      const set2 =
        role === '君'
          ? candidate2Roles['君']
          : role === '臣'
            ? candidate2Roles['臣']
            : role === '佐'
              ? candidate2Roles['佐']
              : candidate2Roles['使'];

      const added = [...set2].filter((x) => !set1.has(x));
      const removed = [...set1].filter((x) => !set2.has(x));

      added.forEach((h) => diffs.push({ type: 'added', herb: h, role, text: `方案二增加${role}药 ${h}` }));
      removed.forEach((h) => diffs.push({ type: 'removed', herb: h, role, text: `方案一独有${role}药 ${h}` }));
    });
    return diffs;
  };

  const roleDiffs = candidates.length === 2 ? getRoleDifferences() : [];

  return (
    <Card className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Brain className="w-5 h-5 text-primary-500" />
          <h3 className="font-semibold">候选方案对比</h3>
        </div>
        <Badge variant="neutral" size="sm">
          {candidates.length} 套方案
        </Badge>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full border-collapse">
          <thead>
            <tr className="bg-gradient-to-r from-primary-50 to-primary-100/50 dark:from-primary-900/20 dark:to-primary-800/10">
              <th className="px-4 py-3 text-left text-xs font-bold text-primary-800 dark:text-primary-200 border-b-2 border-primary-300 dark:border-primary-600">
                指标
              </th>
              {candidates.map((c, i) => (
                <th
                  key={i}
                  className={`px-4 py-3 text-center text-xs font-bold border-b-2 border-primary-300 dark:border-primary-600 ${
                    selectedIndex === i
                      ? 'bg-primary-100/50 dark:bg-primary-300/25 text-primary-700 dark:text-primary-700'
                      : 'text-primary-800 dark:text-primary-200'
                  }`}
                >
                  <div className="space-y-1">
                    <div className="flex items-center justify-center gap-1">
                      <Brain className="w-3 h-3" />
                      <span>方案 {i + 1}</span>
                    </div>
                    <div className="text-sm font-semibold">
                      {typeof c.formula_name === 'string' ? c.formula_name : '未知配方'}
                    </div>
                  </div>
                </th>
              ))}
              <th className="px-4 py-3 text-center text-xs font-bold text-primary-800 dark:text-primary-200 border-b-2 border-primary-300 dark:border-primary-600">
                <div className="flex items-center justify-center gap-1">
                  <ArrowUpDown className="w-3 h-3" />
                  差异分析
                </div>
              </th>
            </tr>
          </thead>
          <tbody>
            {scoreDimensions.map((dim, dimIdx) => {
              const compare =
                dimIdx === 0
                  ? overallCompare
                  : dimIdx === 1
                    ? synergyCompare
                    : dimIdx === 2
                      ? tasteCompare
                      : stabilityCompare;
              const values =
                dimIdx === 0
                  ? overallScores
                  : dimIdx === 1
                    ? synergyScores
                    : dimIdx === 2
                      ? tasteScores
                      : stabilityScores;

              return (
                <tr
                  key={dim.key}
                  className={`${dimIdx % 2 === 0 ? 'bg-white dark:bg-neutral-800' : 'bg-neutral-50/50 dark:bg-neutral-900/30'} hover:bg-primary-50/20 transition-colors`}
                >
                  <td className="px-4 py-3 text-sm font-medium text-neutral-700 dark:text-neutral-300 border-r border-neutral-100 dark:border-neutral-700">
                    {dim.label}
                  </td>
                  {values.map((val, i) => (
                    <td
                      key={i}
                      className={`${getCellClass(compare.differences[i], i === compare.bestIndex)} border-r border-neutral-100 dark:border-neutral-700`}
                    >
                      <div className="flex items-center justify-center gap-1">
                        {getDifferenceIcon(compare.differences[i])}
                        <span>{dim.format ? dim.format(val) : val}</span>
                      </div>
                    </td>
                  ))}
                  <td className="px-4 py-3 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] text-center">
                    {compare.differences.filter((d) => d === 'up').length > 0 && (
                      <span className="text-danger-500">
                        方案 {compare.differences.findIndex((d) => d === 'up') + 1} 更优
                      </span>
                    )}
                    {compare.differences.every((d) => d === 'same') && <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">持平</span>}
                  </td>
                </tr>
              );
            })}

            <tr className={`bg-white dark:bg-neutral-800 hover:bg-primary-50/20 transition-colors`}>
              <td className="px-4 py-3 text-sm font-medium text-neutral-700 dark:text-neutral-300 border-r border-neutral-100 dark:border-neutral-700">
                安全状态
              </td>
              {safetyOk.map((ok, i) => (
                <td key={i} className="px-4 py-3 text-center border-r border-neutral-100 dark:border-neutral-700">
                  {ok ? (
                    <span className="inline-flex items-center gap-1 text-success-600 text-sm">
                      <CheckCircle className="w-4 h-4" /> 安全
                    </span>
                  ) : (
                    <span className="inline-flex items-center gap-1 text-warning-600 text-sm">
                      <AlertTriangle className="w-4 h-4" /> 预警
                    </span>
                  )}
                </td>
              ))}
              <td className="px-4 py-3 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] text-center">
                {safetyOk[0] !== safetyOk[1] && (
                  <Badge variant="warning" size="sm">
                    安全状态不同
                  </Badge>
                )}
                {safetyOk[0] === safetyOk[1] && <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">状态一致</span>}
              </td>
            </tr>

            <tr className={`bg-neutral-50/50 dark:bg-neutral-900/30 hover:bg-primary-50/20 transition-colors`}>
              <td className="px-4 py-3 text-sm font-medium text-neutral-700 dark:text-neutral-300 border-r border-neutral-100 dark:border-neutral-700">
                药材数量
              </td>
              {herbCounts.map((count, i) => (
                <td
                  key={i}
                  className="px-4 py-3 text-center text-sm text-neutral-600 dark:text-neutral-400 border-r border-neutral-100 dark:border-neutral-700"
                >
                  {count} 味
                </td>
              ))}
              <td className="px-4 py-3 text-xs text-center">
                {herbCounts[0] !== herbCounts[1] && (
                  <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">相差 {Math.abs(herbCounts[0] - herbCounts[1])} 味</span>
                )}
                {herbCounts[0] === herbCounts[1] && <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">数量相同</span>}
              </td>
            </tr>

            <tr className={`bg-white dark:bg-neutral-800 hover:bg-primary-50/20 transition-colors`}>
              <td className="px-4 py-3 text-sm font-medium text-neutral-700 dark:text-neutral-300 border-r border-neutral-100 dark:border-neutral-700">
                活性肽
              </td>
              {peptideCounts.map((count, i) => (
                <td
                  key={i}
                  className="px-4 py-3 text-center text-sm text-neutral-600 dark:text-neutral-400 border-r border-neutral-100 dark:border-neutral-700"
                >
                  {count} 个
                </td>
              ))}
              <td className="px-4 py-3 text-xs text-center">
                {peptideCounts[0] !== peptideCounts[1] && (
                  <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">相差 {Math.abs(peptideCounts[0] - peptideCounts[1])} 个</span>
                )}
                {peptideCounts[0] === peptideCounts[1] && <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">数量相同</span>}
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      {roleDiffs.length > 0 && (
        <div className="border-t border-neutral-200 dark:border-neutral-700 pt-4">
          <h4 className="text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-3 flex items-center gap-2">
            <AlertTriangle className="w-4 h-4 text-warning-500" />
            配方组成差异分析
          </h4>
          <div className="space-y-2">
            {roleDiffs.map((diff, i) => (
              <div
                key={i}
                className={`flex items-center gap-2 text-xs px-3 py-2 rounded-lg ${
                  diff.type === 'added'
                    ? 'bg-success-50/50 dark:bg-success-300/20 text-success-600 dark:text-success-600'
                    : 'bg-danger-50/50 dark:bg-danger-300/20 text-danger-600 dark:text-danger-600'
                }`}
              >
                {diff.type === 'added' ? <TrendingUp className="w-3 h-3" /> : <TrendingDown className="w-3 h-3" />}
                <span>{diff.text}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {candidates.length > 2 && (
        <div className="border-t border-neutral-200 dark:border-neutral-700 pt-4">
          <h4 className="text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-3">药材组成</h4>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {candidates.map((c, i) => (
              <div key={i} className="bg-neutral-50/50 dark:bg-neutral-800/50 rounded-lg p-3">
                <div className="text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-2">
                  方案 {i + 1}: {typeof c.formula_name === 'string' ? c.formula_name : '未知配方'}
                </div>
                <div className="space-y-1">
                  {(c.herb_combination ?? []).map((h, j) => (
                    <div key={j} className="flex items-center justify-between text-xs">
                      <span className="text-neutral-600 dark:text-neutral-400">
                        {typeof h.name === 'string' ? h.name : '未知药材'}
                      </span>
                      <Badge variant="neutral" size="sm">
                        {typeof h.role === 'string' ? h.role : '其他'}
                      </Badge>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="flex justify-center gap-3 pt-2">
        {candidates.map((c, i) => (
          <Button
            key={i}
            variant={selectedIndex === i ? 'primary' : 'secondary'}
            size="sm"
            onClick={() => onSelectCandidate?.(c)}
          >
            选择方案 {i + 1}
          </Button>
        ))}
      </div>
    </Card>
  );
}

export default MultiCandidateCompare;

/**
 * PromptOptimizer - AI提示词质量优化器
 *
 * 提供完整的提示词分析和优化功能：
 * - 语法检查（实时高亮问题）
 * - 结构分析（四要素完整性）
 * - 效果预测（评分模型）
 * - LLM智能优化建议
 * - 一键应用修复
 *
 * @version 2.0.0
 * @lastUpdated 2026-05-20
 */

import { useState, useCallback, useEffect } from 'react'
import {
  Wrench,
  CheckCircle2,
  AlertTriangle,
  Info,
  XCircle,
  Sparkles,
  Copy,
  Check,
  Loader2,
  ChevronRight,
  TrendingUp,
  FileText,
  Bug,
  Layout,
  BarChart3,
  RefreshCw,
} from 'lucide-react'
import { Button, Textarea, Badge, Card, Progress } from '@/components/ui'
import { logger } from '@/utils/safeLogger'

// ===== 类型定义 =====

type OptimizationLevel = 'basic' | 'advanced' | 'expert'

interface SyntaxIssue {
  id: string
  severity: 'error' | 'warning' | 'info'
  rule_id: string
  message: string
  line_number: number
  snippet: string
  suggestion: string
}

interface StructureSection {
  name: string
  is_present: boolean
  position: number
  quality_score: number
}

interface StructureReport {
  overall_score: number
  sections: Record<string, StructureSection>
  strengths: string[]
  weaknesses: string[]
  structure_type: string
}

interface EffectivenessPrediction {
  score: number
  confidence_interval: [number, number]
  feature_scores: Record<string, number>
  strengths: string[]
  weaknesses: string[]
  improvement_potential: number
}

interface OptimizationSuggestion {
  id: string
  severity: 'critical' | 'major' | 'minor' | 'suggestion'
  category: string
  title: string
  description: string
  location: string
  before: string
  after: string
  impact_estimate: string
  is_auto_fixable: boolean
}

interface OptimizationResult {
  original_content: string
  optimized_content: string | null
  syntax_issues: SyntaxIssue[]
  structure_report: StructureReport | null
  effectiveness_prediction: EffectivenessPrediction | null
  suggestions: OptimizationSuggestion[]
  overall_score_before: number
  overall_score_after: number
  score_improvement: number
  processing_time_ms: number
}

// ===== 常量配置 =====

const LEVEL_CONFIG = {
  basic: {
    label: '基础分析',
    description: '语法检查 + 结构评估',
    color: 'blue',
  },
  advanced: {
    label: '深度优化',
    description: '全部分析 + LLM建议',
    color: 'purple',
  },
  expert: {
    label: '专家级',
    description: '完整优化 + 自动改写',
    color: 'orange',
  },
} as const

// ===== 主组件 =====

interface PromptOptimizerProps {
  initialContent?: string
  onOptimizeComplete?: (result: OptimizationResult) => void
  className?: string
}

export function PromptOptimizer({
  initialContent = '',
  onOptimizeComplete,
  className = '',
}: PromptOptimizerProps) {
  const [content, setContent] = useState(initialContent)
  const [level, setLevel] = useState<OptimizationLevel>('advanced')
  const [isAnalyzing, setIsAnalyzing] = useState(false)
  const [result, setResult] = useState<OptimizationResult | null>(null)
  const [activeTab, setActiveTab] = useState<'issues' | 'structure' | 'effectiveness' | 'suggestions'>('issues')
  const [selectedIssueIndex, setSelectedIssueIndex] = useState<number | null>(null)
  const [appliedFixes, setAppliedFixes] = useState<Set<string>>(new Set())
  const [showOptimizedVersion, setShowOptimizedVersion] = useState(false)
  const [copied, setCopied] = useState(false)

  useEffect(() => {
    if (initialContent && !result) {
      // eslint-disable-next-line react-hooks/immutability
      handleAnalyze()
    }
  }, [])

  // eslint-disable-next-line react-hooks/preserve-manual-memoization
  const handleAnalyze = useCallback(async () => {
    if (!content.trim()) return

    setIsAnalyzing(true)
    setResult(null)
    setAppliedFixes(new Set())

    try {
      const response = await fetch('/api/v1/ai/optimize', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          prompt_content: content,
          optimization_level: level,
          goals: [],
        }),
      })

      if (!response.ok) throw new Error(`HTTP ${response.status}`)

      const data: OptimizationResult = await response.json()
      setResult(data)

      onOptimizeComplete?.(data)

      logger.info('Optimization completed', {
        score_before: data.overall_score_before,
        score_after: data.overall_score_after,
        improvement: data.score_improvement,
      })
    } catch (err: unknown) {
      logger.error('Optimization failed:', err)
    } finally {
      setIsAnalyzing(false)
    }
  }, [content, level, onOptimizeComplete])

  const handleApplyFix = useCallback(
    (suggestion: OptimizationSuggestion) => {
      if (!suggestion.is_auto_fixable || !suggestion.before || !suggestion.after) return

      setContent((prev) => prev.replace(suggestion.before, suggestion.after))
      setAppliedFixes((prev) => new Set(prev).add(suggestion.id))
    },
    [],
  )

  const handleApplyAllAutoFixes = useCallback(() => {
    if (!result) return

    let updatedContent = content
    const newlyApplied = new Set(appliedFixes)

    result.suggestions.forEach((suggestion) => {
      if (
        suggestion.is_auto_fixable &&
        suggestion.before &&
        suggestion.after &&
        !appliedFixes.has(suggestion.id)
      ) {
        if (updatedContent.includes(suggestion.before)) {
          updatedContent = updatedContent.replace(suggestion.before, suggestion.after)
          newlyApplied.add(suggestion.id)
        }
      }
    })

    setContent(updatedContent)
    setAppliedFixes(newlyApplied)
  }, [result, content, appliedFixes])

  const handleCopyOptimized = useCallback(async () => {
    const textToCopy = showOptimizedVersion && result?.optimized_content
      ? result.optimized_content
      : content

    try {
      await navigator.clipboard.writeText(textToCopy)
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    } catch (err) {
      logger.error('Copy failed:', err)
    }
  }, [content, result, showOptimizedVersion])

  const getSeverityIcon = (severity: string) => {
    switch (severity) {
      case 'error':
      case 'critical':
        return <XCircle size={16} className="text-error-600" />
      case 'warning':
      case 'major':
        return <AlertTriangle size={16} className="text-warning-600" />
      default:
        return <Info size={16} className="text-secondary-600" />
    }
  }

  const getScoreColor = (score: number) => {
    if (score >= 90) return 'text-success-600'
    if (score >= 70) return 'text-warning-600'
    return 'text-error-600'
  }

  return (
    <div className={`space-y-4 ${className}`}>
      {/* 输入区域 */}
      <Card className="p-4">
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <h3 className="text-sm font-semibold text-neutral-900 dark:text-neutral-100 flex items-center gap-2">
              <FileText size={16} />
              待优化的提示词
            </h3>

            <div className="flex items-center gap-2">
              {(Object.keys(LEVEL_CONFIG) as OptimizationLevel[]).map((lvl) => (
                <button
                  key={lvl}
                  onClick={() => setLevel(lvl)}
                  className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${
                    level === lvl
                      ? `bg-${LEVEL_CONFIG[lvl].color}-100 text-${LEVEL_CONFIG[lvl].color}-700 border border-${LEVEL_CONFIG[lvl].color}-300`
                      : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-600 hover:bg-neutral-200'
                  }`}
                >
                  {LEVEL_CONFIG[lvl].label}
                </button>
              ))}
            </div>
          </div>

          <Textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="在此粘贴或输入需要优化的提示词..."
            rows={8}
            className="font-mono text-sm"
            disabled={isAnalyzing}
          />

          <div className="flex items-center justify-between pt-2">
            <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
              字符数: {content.length} · 建议长度: 200-1500字符
            </p>

            <Button onClick={handleAnalyze} disabled={!content.trim() || isAnalyzing} variant="primary" size="sm">
              {isAnalyzing ? (
                <>
                  <Loader2 size={16} className="animate-spin mr-1" />
                  分析中...
                </>
              ) : (
                <>
                  <Wrench size={16} className="mr-1" />
                  开始优化
                </>
              )}
            </Button>
          </div>
        </div>
      </Card>

      {/* 分析结果区域 */}
      {result && (
        <Card className="p-4">
          {/* 总览卡片 */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-4 p-4 bg-gradient-to-r from-secondary-50 to-accent-50 dark:from-secondary-900/20 dark:to-accent-900/20 rounded-lg">
            <div className="text-center">
              <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">原始分数</p>
              <p className={`text-2xl font-bold ${getScoreColor(result.overall_score_before)}`}>
                {result.overall_score_before.toFixed(0)}
              </p>
            </div>

            <div className="text-center">
              <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">优化后预估</p>
              <p className={`text-2xl font-bold ${getScoreColor(result.overall_score_after)}`}>
                {result.overall_score_after.toFixed(0)}
              </p>
            </div>

            <div className="text-center">
              <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">提升幅度</p>
              <p className="text-2xl font-bold text-success-600 flex items-center justify-center gap-1">
                <TrendingUp size={18} />
                +{result.score_improvement.toFixed(0)}
              </p>
            </div>
          </div>

          {/* 标签页切换 */}
          <div className="flex items-center gap-2 border-b mb-4 overflow-x-auto pb-2">
            <button
              onClick={() => setActiveTab('issues')}
              className={`px-3 py-1.5 text-sm font-medium rounded-t transition-colors whitespace-nowrap ${
                activeTab === 'issues'
                  ? 'bg-white dark:bg-neutral-800 border-b-2 border-secondary-600 text-secondary-600'
                  : 'text-neutral-600 hover:text-neutral-900'
              }`}
            >
              <Bug size={14} className="inline mr-1" />
              问题 ({result.syntax_issues.length})
            </button>

            <button
              onClick={() => setActiveTab('structure')}
              className={`px-3 py-1.5 text-sm font-medium rounded-t transition-colors whitespace-nowrap ${
                activeTab === 'structure'
                  ? 'bg-white dark:bg-neutral-800 border-b-2 border-secondary-600 text-secondary-600'
                  : 'text-neutral-600 hover:text-neutral-900'
              }`}
            >
              <Layout size={14} className="inline mr-1" />
              结构 ({result.structure_report?.overall_score.toFixed(0) || '-'})
            </button>

            <button
              onClick={() => setActiveTab('effectiveness')}
              className={`px-3 py-1.5 text-sm font-medium rounded-t transition-colors whitespace-nowrap ${
                activeTab === 'effectiveness'
                  ? 'bg-white dark:bg-neutral-800 border-b-2 border-secondary-600 text-secondary-600'
                  : 'text-neutral-600 hover:text-neutral-900'
              }`}
            >
              <BarChart3 size={14} className="inline mr-1" />
              效果预测 ({result.effectiveness_prediction?.score.toFixed(0) || '-'})
            </button>

            <button
              onClick={() => setActiveTab('suggestions')}
              className={`px-3 py-1.5 text-sm font-medium rounded-t transition-colors whitespace-nowrap ${
                activeTab === 'suggestions'
                  ? 'bg-white dark:bg-neutral-800 border-b-2 border-secondary-600 text-secondary-600'
                  : 'text-neutral-600 hover:text-neutral-900'
              }`}
            >
              <Sparkles size={14} className="inline mr-1" />
              建议 ({result.suggestions.length})
            </button>
          </div>

          {/* 标签内容 */}
          <div className="min-h-[300px]">
            {/* 问题列表 */}
            {activeTab === 'issues' && (
              <div className="space-y-2">
                {result.syntax_issues.length === 0 ? (
                  <div className="text-center py-8 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                    <CheckCircle2 size={48} className="mx-auto mb-2 text-success-500" />
                    <p>未发现语法问题 ✓</p>
                  </div>
                ) : (
                  result.syntax_issues.map((issue, index) => (
                    <div
                      key={`${issue.rule_id}-${index}`}
                      className={`p-3 rounded-lg border cursor-pointer transition-colors ${
                        selectedIssueIndex === index
                          ? 'bg-secondary-50 border-secondary-300 dark:bg-secondary-300/20'
                          : 'bg-neutral-50 dark:bg-neutral-800 hover:bg-neutral-100 dark:bg-neutral-800 border-transparent'
                      }`}
                       role="button" tabIndex={0} onClick={() =>
                        setSelectedIssueIndex(selectedIssueIndex === index ? null : index)
                      }
                    >
                      <div className="flex items-start gap-3">
                        {getSeverityIcon(issue.severity)}
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium text-neutral-900 dark:text-neutral-100">
                            {issue.message}
                          </p>
                          <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1 line-clamp-2">
                            第{issue.line_number}行: {issue.snippet}
                          </p>
                          {selectedIssueIndex === index && issue.suggestion && (
                            <p className="text-xs text-secondary-600 mt-2 p-2 bg-secondary-50 rounded">
                              💡 {issue.suggestion}
                            </p>
                          )}
                        </div>
                        <Badge variant={
                          issue.severity === 'error' ? 'danger' :
                          issue.severity === 'warning' ? 'warning' : 'info'
                        }>
                          {issue.severity}
                        </Badge>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}

            {/* 结构分析 */}
            {activeTab === 'structure' && result.structure_report && (
              <div className="space-y-4">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="p-3 bg-neutral-50 dark:bg-neutral-800 rounded-lg">
                    <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">结构类型</p>
                    <p className="text-lg font-semibold capitalize">
                      {result.structure_report.structure_type.replace('_', ' ')}
                    </p>
                  </div>
                  <div className="p-3 bg-neutral-50 dark:bg-neutral-800 rounded-lg">
                    <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">总体得分</p>
                    <p className={`text-lg font-semibold ${getScoreColor(result.structure_report.overall_score)}`}>
                      {result.structure_report.overall_score.toFixed(0)}/100
                    </p>
                  </div>
                </div>

                <div className="space-y-2">
                  {Object.entries(result.structure_report.sections).map(([name, section]) => (
                    <div key={name} className="flex items-center justify-between p-2 bg-neutral-50 dark:bg-neutral-800 rounded">
                      <span className="text-sm font-medium">{name}</span>
                      <div className="flex items-center gap-2">
                        {section.is_present ? (
                          <CheckCircle2 size={16} className="text-success-600" />
                        ) : (
                          <XCircle size={16} className="text-error-600" />
                        )}
                        <span className="text-sm text-neutral-600">
                          {section.is_present ? `${(section.quality_score * 100).toFixed(0)}%` : '缺失'}
                        </span>
                      </div>
                    </div>
                  ))}
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <p className="text-xs font-semibold text-success-700 mb-2">✅ 优势</p>
                    <ul className="space-y-1">
                      {result.structure_report.strengths.map((s, i) => (
                        <li key={i} className="text-xs text-neutral-600 pl-2">• {s}</li>
                      ))}
                    </ul>
                  </div>
                  <div>
                    <p className="text-xs font-semibold text-error-700 mb-2">⚠️ 不足</p>
                    <ul className="space-y-1">
                      {result.structure_report.weaknesses.map((w, i) => (
                        <li key={i} className="text-xs text-neutral-600 pl-2">• {w}</li>
                      ))}
                    </ul>
                  </div>
                </div>
              </div>
            )}

            {/* 效果预测 */}
            {activeTab === 'effectiveness' && result.effectiveness_prediction && (
              <div className="space-y-4">
                <div className="p-4 bg-gradient-to-r from-success-50 to-success-50 rounded-lg text-center">
                  <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">综合效果评分</p>
                  <p className={`text-4xl font-bold ${getScoreColor(result.effectiveness_prediction.score)}`}>
                    {result.effectiveness_prediction.score.toFixed(0)}
                  </p>
                  <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">
                    置信区间: [{result.effectiveness_prediction.confidence_interval[0]},{' '}
                    {result.effectiveness_prediction.confidence_interval[1]}]
                  </p>
                </div>

                <div>
                  <p className="text-xs font-semibold text-neutral-700 mb-2">特征得分详情</p>
                  <div className="space-y-2">
                    {Object.entries(result.effectiveness_prediction.feature_scores).map(([feature, score]) => (
                      <div key={feature}>
                        <div className="flex justify-between text-xs mb-1">
                          <span>{feature.replace(/_/g, ' ')}</span>
                          <span>{(score * 100).toFixed(0)}%</span>
                        </div>
                        <Progress value={score * 100} />
                      </div>
                    ))}
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 p-3 bg-warning-50 rounded-lg">
                  <div>
                    <p className="text-xs font-semibold text-success-700 mb-1">✨ 优势特征</p>
                    <ul className="space-y-0.5">
                      {result.effectiveness_prediction.strengths.map((s, i) => (
                        <li key={i} className="text-xs text-neutral-600">• {s}</li>
                      ))}
                    </ul>
                  </div>
                  <div>
                    <p className="text-xs font-semibold text-warning-700 mb-1">⚡ 提升空间</p>
                    <ul className="space-y-0.5">
                      {result.effectiveness_prediction.weaknesses.map((w, i) => (
                        <li key={i} className="text-xs text-neutral-600">• {w}</li>
                      ))}
                    </ul>
                  </div>
                </div>
              </div>
            )}

            {/* 优化建议 */}
            {activeTab === 'suggestions' && (
              <div className="space-y-3">
                {result.suggestions.length === 0 ? (
                  <div className="text-center py-8 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                    <Sparkles size={48} className="mx-auto mb-2 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
                    <p>暂无优化建议，您的提示词已经很棒了！</p>
                  </div>
                ) : (
                  <>
                    <div className="flex items-center justify-between">
                      <p className="text-sm text-neutral-600">
                        可自动修复: {result.suggestions.filter((s) => s.is_auto_fixable).length}项
                      </p>
                      <Button
                        onClick={handleApplyAllAutoFixes}
                        variant="secondary"
                        size="sm"
                        disabled={appliedFixes.size === result.suggestions.filter((s) => s.is_auto_fixable).length}
                      >
                        <RefreshCw size={14} className="mr-1" />
                        应用所有修复
                      </Button>
                    </div>

                    {result.suggestions.map((suggestion) => (
                      <div
                        key={suggestion.id}
                        className={`p-3 rounded-lg border ${
                          appliedFixes.has(suggestion.id)
                            ? 'bg-success-50 border-success-200'
                            : 'bg-neutral-50 dark:bg-neutral-800 border-neutral-200'
                        }`}
                      >
                        <div className="flex items-start justify-between gap-3">
                          <div className="flex-1">
                            <div className="flex items-center gap-2 mb-1">
                              {getSeverityIcon(suggestion.severity)}
                              <p className="text-sm font-semibold text-neutral-900">
                                {suggestion.title}
                              </p>
                              {appliedFixes.has(suggestion.id) && (
                                <Badge variant="success" size="sm">已修复</Badge>
                              )}
                            </div>
                            <p className="text-xs text-neutral-600 mb-2">{suggestion.description}</p>

                            {suggestion.before && suggestion.after && (
                              <div className="text-xs space-y-1">
                                <div className="p-2 bg-error-50 rounded font-mono line-clamp-2">
                                  <span className="text-error-600 font-bold">-</span> {suggestion.before}
                                </div>
                                <ChevronRight size={14} className="mx-auto text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
                                <div className="p-2 bg-success-50 rounded font-mono line-clamp-2">
                                  <span className="text-success-600 font-bold">+</span> {suggestion.after}
                                </div>
                              </div>
                            )}

                            {suggestion.impact_estimate && (
                              <p className="text-xs text-secondary-600 mt-2">
                                📈 预期提升: {suggestion.impact_estimate}
                              </p>
                            )}
                          </div>

                          {suggestion.is_auto_fixable && !appliedFixes.has(suggestion.id) && (
                            <Button
                              onClick={() => handleApplyFix(suggestion)}
                              variant="outline"
                              size="sm"
                            >
                              应用
                            </Button>
                          )}
                        </div>
                      </div>
                    ))}
                  </>
                )}
              </div>
            )}
          </div>

          {/* 优化后版本切换 */}
          {result.optimized_content && level === 'expert' && (
            <div className="mt-4 pt-4 border-t">
              <div className="flex items-center justify-between mb-3">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={showOptimizedVersion}
                    onChange={(e) => setShowOptimizedVersion(e.target.checked)}
                    className="rounded"
                  />
                  <span className="text-sm font-medium text-neutral-900">
                    查看LLM优化后的完整版本
                  </span>
                </label>

                <Button onClick={handleCopyOptimized} variant="outline" size="sm">
                  {copied ? <Check size={14} /> : <Copy size={14} />}
                  {copied ? '已复制' : '复制'}
                </Button>
              </div>

              {showOptimizedVersion && (
                <div className="p-4 bg-gradient-to-br from-success-50 to-success-50 dark:from-success-900/10 dark:to-success-900/10 rounded-lg max-h-[400px] overflow-y-auto">
                  <pre className="text-sm whitespace-pre-wrap font-mono leading-relaxed">
                    {result.optimized_content}
                  </pre>
                </div>
              )}
            </div>
          )}
        </Card>
      )}
    </div>
  )
}

export default PromptOptimizer

