/**
 * SearchModal — 全局搜索模态框
 *
 * 支持 Ctrl+K / Cmd+K 快捷键打开。
 * 搜索范围：配方、实验、原料。
 * 调用 GET /api/v1/search/global（真实端点，跨类型模糊搜索）。
 *
 * 此前指向 /api/v1/ai/search —— 该路由后端不存在，fetch 返回 404 后被
 * catch 成空结果，用户看到的是"未找到匹配结果"，误以为搜索功能正常但库里
 * 没有数据；实际是搜索根本没执行。
 */
import { useState, useCallback, useRef, useEffect } from 'react';
import { Search, X } from 'lucide-react';
import type { SearchResult } from '@/types/ai.api';

interface SearchModalProps {
  isOpen: boolean;
  onClose: () => void;
}

/** 后端 /search/global 返回 items[].description，前端类型字段叫 snippet */
function normalizeSearchItems(data: unknown): SearchResult[] {
  const payload = data as { types?: Record<string, { items?: unknown[] }> };
  const out: SearchResult[] = [];
  const seen = new Set<string>();
  for (const bucket of Object.values(payload?.types ?? {})) {
    for (const raw of (bucket?.items ?? []) as Array<Record<string, unknown>>) {
      const id = String(raw.id ?? '');
      if (!id || seen.has(id)) continue;
      seen.add(id);
      const type = String(raw.type ?? '') as SearchResult['type'];
      out.push({
        id,
        type: type === 'formula' || type === 'ingredient' || type === 'experiment' ? type : 'analysis',
        title: String(raw.title ?? ''),
        snippet: String(raw.description ?? ''),
        score: typeof raw.score === 'number' ? raw.score : 0,
      });
    }
  }
  return out.sort((a, b) => b.score - a.score);
}

export function SearchModal({ isOpen, onClose }: SearchModalProps) {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [searchError, setSearchError] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isOpen]);

  // 防抖搜索
  useEffect(() => {
    if (!query.trim()) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setResults([]);
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setSearchError(null);
      return;
    }
    const timer = setTimeout(async () => {
      setIsSearching(true);
      try {
        const url = `/api/v1/search/global?q=${encodeURIComponent(query)}&types=formula,experiment,ingredient&page_size=20`;
        const response = await fetch(url);
        if (response.ok) {
          const data = await response.json();
          setResults(normalizeSearchItems(data));
        }
        // 非 200（鉴权/服务异常）不再静默降级成"无结果"，明确标记失败
        else {
          setResults([]);
          setSearchError(`搜索服务异常（HTTP ${response.status}）`);
        }
      } catch {
        setResults([]);
        setSearchError('搜索服务不可达');
      } finally {
        setIsSearching(false);
      }
    }, 300);
    return () => clearTimeout(timer);
  }, [query]);

  const handleClose = useCallback(() => {
    setQuery('');
    setResults([]);
    onClose();
  }, [onClose]);

  if (!isOpen) return null;

  return (
    <div
      className="fixed inset-0 z-[500] flex items-start justify-center pt-24 px-4"
      role="dialog"
      aria-modal="true"
      aria-label="全局搜索"
    >
      {/* 背景遮罩 */}
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm"  role="button" tabIndex={0} onClick={handleClose} />

      {/* 搜索框 */}
      <div className="relative w-full max-w-2xl bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-md)] shadow-2xl border border-[var(--border-color)] overflow-hidden">
        {/* 输入区 */}
        <div className="flex items-center px-[var(--space-apple-md)] py-[var(--space-apple-sm)] border-b border-[var(--border-color)]">
          <Search className="w-5 h-5 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] flex-shrink-0" />
          <input
            ref={inputRef}
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="搜索配方、药材、分析工具..."
            className="flex-1 ml-3 bg-transparent text-base focus:outline-none text-neutral-900 dark:text-white placeholder:text-[color:var(--text-muted)] dark:placeholder:text-[color:var(--text-secondary)]"
            aria-label="搜索内容"
          />
          <button
            onClick={handleClose}
            className="ml-2 p-1 rounded hover:bg-neutral-100 dark:hover:bg-neutral-700 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]"
            aria-label="关闭搜索"
          >
            <X className="w-4 h-4" />
          </button>
          <kbd className="ml-3 px-2 py-1 text-xs font-mono text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] bg-neutral-100 dark:bg-neutral-700 rounded">
            ESC
          </kbd>
        </div>

        {/* 结果区 */}
        <div className="max-h-96 overflow-y-auto p-2">
          {isSearching ? (
            <div className="px-4 py-8 text-center text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">搜索中...</div>
          ) : results.length > 0 ? (
            <div className="space-y-1">
              {results.map((r) => (
                <button
                  key={r.id}
                  className="w-full text-left px-4 py-3 rounded-lg hover:bg-neutral-50 dark:hover:bg-neutral-700/50 transition-colors"
                  onClick={handleClose}
                >
                  <div className="flex items-center gap-3">
                    <span
                      className={`w-2 h-2 rounded-full ${
                        r.type === 'formula'
                          ? 'bg-secondary-500'
                          : r.type === 'ingredient'
                            ? 'bg-primary-500'
                            : 'bg-accent-500'
                      }`}
                    />
                    <div>
                      <div className="text-sm font-medium text-neutral-900 dark:text-white">{r.title}</div>
                      <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] truncate">{r.snippet}</div>
                    </div>
                  </div>
                </button>
              ))}
            </div>
          ) : searchError ? (
            <div className="px-4 py-8 text-center text-sm text-error-500">{searchError}</div>
          ) : query.trim() ? (
            <div className="px-4 py-8 text-center text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">未找到匹配 "{query}" 的结果</div>
          ) : (
            <div className="px-4 py-8 text-center text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">输入关键词开始搜索</div>
          )}
        </div>
      </div>
    </div>
  );
}

export default SearchModal;

/**
 * Bot 对话服务（DS Bot 移植）
 *
 * 复用后端成熟对话链路：POST /ai/chat 与 /ai/chat/stream（SSE），
 * 请求体携带 bot_id，后端以 Bot 的人设+记忆+模型覆盖应答（评审 M2/R7）。
 */
import api from '@/api/client';
import { envConfig } from '@/config/env';

export interface BotChatResponse {
  content: string;
  role?: string;
  model?: string | null;
  formulas?: unknown[];
  thinking_steps?: Array<{ step: string; content: string; status: string; detail?: string }>;
  success?: boolean;
}

export interface BotChatHistoryItem {
  role: string;
  content: string;
}

export interface BotChatStreamHandlers {
  onMeta?: (model: string) => void;
  onContent: (chunk: string) => void;
  onDone: () => void;
  onError: (error: Error) => void;
}

/** 非流式 Bot 对话 */
export async function botChat(
  botId: number,
  question: string,
  history: BotChatHistoryItem[] = [],
): Promise<BotChatResponse> {
  const res = await api.post<BotChatResponse>('/ai/chat', {
    question,
    history,
    stream: false,
    bot_id: botId,
  });
  return res.data;
}

/** 流式 Bot 对话（SSE），返回 abort 函数 */
export function botChatStream(
  botId: number,
  question: string,
  history: BotChatHistoryItem[] = [],
  handlers: BotChatStreamHandlers,
): () => void {
  const controller = new AbortController();

  const request = async () => {
    try {
      const res = await fetch(`${envConfig.api.baseUrl}/ai/chat/stream`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          question,
          history,
          stream: true,
          bot_id: botId,
        }),
        credentials: 'include',
        signal: controller.signal,
      });
      if (!res.ok) {
        const text = await res.text().catch(() => '');
        throw new Error(`Bot 对话失败 (${res.status}): ${text.slice(0, 200)}`);
      }
      const reader = res.body?.getReader();
      if (!reader) throw new Error('无响应流');

      const decoder = new TextDecoder();
      let buffer = '';
      let accumulated = '';
      let currentEvent = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() ?? '';

        for (const line of lines) {
          // SSE event 名与 data 分离：`event: meta` + `data: {...}`
          if (line.startsWith('event: ')) {
            currentEvent = line.slice(7).trim();
            continue;
          }
          if (!line.startsWith('data: ')) continue;
          const dataStr = line.slice(6).trim();
          if (!dataStr || dataStr === '[DONE]') continue;
          try {
            const parsed = JSON.parse(dataStr);
            if (currentEvent === 'meta' && parsed.model) {
              handlers.onMeta?.(parsed.model);
            } else if (currentEvent === 'content' && typeof parsed.content === 'string') {
              void accumulated;
              handlers.onContent(parsed.content);
            }
          } catch {
            // 忽略无法解析的行
          }
        }
      }
      handlers.onDone();
    } catch (err) {
      if ((err as Error).name === 'AbortError') return;
      handlers.onError(err instanceof Error ? err : new Error(String(err)));
    }
  };

  void request();
  return () => controller.abort();
}

import React, { useState, useEffect } from 'react';
import { ExportFormat, ExportScope } from '../../../types/export.types';
import type { ExportOptions, ExportColumn, ExportProgress, ExportResult } from '../../../types/export.types';


import { logger } from '@/utils/safeLogger';
interface ExportDialogProps {
  isOpen: boolean;
  columns: ExportColumn[];
  totalRowCount: number;
  selectedRowCount?: number;
  filteredRowCount?: number;
  onExport: (options: ExportOptions) => Promise<ExportResult>;
  onClose: () => void;
}

const ExportDialog: React.FC<ExportDialogProps> = ({
  isOpen,
  columns,
  totalRowCount,
  selectedRowCount = 0,
  filteredRowCount = 0,
  onExport,
  onClose,
}) => {
  const [format, setFormat] = useState<ExportFormat>(ExportFormat.EXCEL);
  const [scope, setScope] = useState<ExportScope>(ExportScope.ALL_DATA);
  const [fileName, setFileName] = useState('');
  const [includeHeader, setIncludeHeader] = useState(true);
  const [includeIndex, setIncludeIndex] = useState(false);
  const [selectedColumns, setSelectedColumns] = useState<string[]>(
    columns.filter(c => c.visible).map(c => c.key),
  );
  const [isExporting, setIsExporting] = useState(false);
  const [progress] = useState<ExportProgress | null>(null);
  const [result, setResult] = useState<ExportResult | null>(null);

  useEffect(() => {
    if (isOpen) {
      const timestamp = new Date().toISOString().slice(0, 10);
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setFileName(`数据导出_${timestamp}`);
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setSelectedColumns(columns.filter(c => c.visible).map(c => c.key));
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setResult(null);
    }
  }, [isOpen, columns]);

  const handleColumnToggle = (columnKey: string) => {
    setSelectedColumns(prev =>
      prev.includes(columnKey)
        ? prev.filter(k => k !== columnKey)
        : [...prev, columnKey],
    );
  };

  const handleSelectAllColumns = () => {
    setSelectedColumns(columns.map(c => c.key));
  };

  const handleDeselectAllColumns = () => {
    setSelectedColumns([]);
  };

  const handleExport = async () => {
    setIsExporting(true);
    setResult(null);

    const options: ExportOptions = {
      format,
      scope,
      columns: columns.map(col => ({
        ...col,
        visible: selectedColumns.includes(col.key),
      })),
      fileName: fileName || undefined,
      includeHeader,
      includeIndex,
    };

    try {
      const exportResult = await onExport(options);
      setResult(exportResult);

      if (exportResult.success) {
        setTimeout(() => {
          onClose();
        }, 2000);
      }
    } catch (error) {
      logger.error('Export failed:', error);
      setResult({
        success: false,
        fileName: '',
        format,
        recordCount: 0,
        error: error instanceof Error ? error.message : '导出失败',
        timestamp: Date.now(),
      });
    } finally {
      setIsExporting(false);
    }
  };

  const getScopeDescription = (): string => {
    switch (scope) {
      case ExportScope.ALL_DATA:
        return `共 ${totalRowCount} 条记录`;
      case ExportScope.CURRENT_PAGE:
        return `当前页数据`;
      case ExportScope.SELECTED_ROWS:
        return `已选 ${selectedRowCount} 条记录`;
      case ExportScope.FILTERED_DATA:
        return `筛选后 ${filteredRowCount} 条记录`;
      default:
        return '';
    }
  };

  const getFormatIcon = (fmt: ExportFormat): string => {
    switch (fmt) {
      case ExportFormat.CSV: return '📊';
      case ExportFormat.EXCEL: return '📗';
      case ExportFormat.JSON: return '{ }';
      case ExportFormat.PDF: return '📄';
      default: return '📁';
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50">
      <div className="bg-white dark:bg-neutral-900 rounded-lg shadow-xl w-full max-w-2xl mx-4 max-h-[90vh] overflow-hidden flex flex-col">
        <div className="px-6 py-4 border-b border-neutral-200 dark:border-neutral-700 flex items-center justify-between">
          <div>
            <h3 className="text-lg font-semibold text-neutral-900 dark:text-neutral-100">导出数据</h3>
            <p className="mt-1 text-sm text-neutral-600">选择导出格式和选项</p>
          </div>
          <button
            onClick={onClose}
            disabled={isExporting}
            className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-neutral-600 disabled:opacity-50"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-4 space-y-6">
          {result && (
            <div className={`p-4 rounded-lg ${result.success ? 'bg-success-50' : 'bg-error-50'}`}>
              <div className="flex items-start">
                <div className={`flex-shrink-0 ${result.success ? 'text-success-400' : 'text-error-400'}`}>
                  {result.success ? (
                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                    </svg>
                  ) : (
                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                    </svg>
                  )}
                </div>
                <div className="ml-3">
                  <p className={`text-sm font-medium ${result.success ? 'text-success-800' : 'text-error-800'}`}>
                    {result.success ? '导出成功！' : '导出失败'}
                  </p>
                  <p className={`mt-1 text-sm ${result.success ? 'text-success-700' : 'text-error-700'}`}>
                    {result.success
                      ? `${result.fileName} (${(result.fileSize! / 1024).toFixed(1)} KB)`
                      : result.error
                    }
                  </p>
                </div>
              </div>
            </div>
          )}

          <div>
            <label className="block text-sm font-medium text-neutral-700 mb-3">
              导出格式
            </label>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
              {Object.values(ExportFormat).map((fmt) => (
                <button
                  key={fmt}
                  onClick={() => setFormat(fmt)}
                  disabled={isExporting}
                  className={`relative p-4 rounded-lg border-2 text-center transition-all ${
                    format === fmt
                      ? 'border-secondary-500 bg-secondary-50 text-secondary-700'
                      : 'border-neutral-200 dark:border-neutral-700 hover:border-neutral-300 dark:border-neutral-700 text-neutral-700'
                  } disabled:opacity-50`}
                >
                  <span className="text-2xl mb-2 block">{getFormatIcon(fmt)}</span>
                  <span className="text-sm font-medium">{fmt.toUpperCase()}</span>
                  {format === fmt && (
                    <span className="absolute top-2 right-2 w-4 h-4 bg-secondary-500 rounded-full flex items-center justify-center">
                      <svg className="w-3 h-3 text-white" fill="currentColor" viewBox="0 0 20 20">
                        <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                      </svg>
                    </span>
                  )}
                </button>
              ))}
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-neutral-700 mb-3">
              导出范围
            </label>
            <div className="space-y-2">
              {[
                { value: ExportScope.ALL_DATA, label: '全部数据', desc: getScopeDescription(), available: true },
                { value: ExportScope.SELECTED_ROWS, label: '选中行', desc: `已选 ${selectedRowCount} 条`, available: selectedRowCount > 0 },
                { value: ExportScope.FILTERED_DATA, label: '筛选结果', desc: filteredRowCount > 0 ? `${filteredRowCount} 条` : '无筛选', available: filteredRowCount > 0 },
                { value: ExportScope.CURRENT_PAGE, label: '当前页', desc: '当前显示的数据', available: true },
              ].map((option) => (
                <label
                  key={option.value}
                  className={`flex items-center p-3 rounded-lg border cursor-pointer transition-all ${
                    scope === option.value
                      ? 'border-secondary-500 bg-secondary-50'
                      : option.available
                      ? 'border-neutral-200 dark:border-neutral-700 hover:border-neutral-300 dark:border-neutral-700'
                      : 'border-neutral-100 opacity-50 cursor-not-allowed'
                  }`}
                >
                  <input
                    type="radio"
                    name="scope"
                    value={option.value}
                    checked={scope === option.value}
                    onChange={() => option.available && setScope(option.value)}
                    disabled={!option.available || isExporting}
                    className="w-4 h-4 text-secondary-600 focus:ring-secondary-500"
                  />
                  <div className="ml-3 flex-1">
                    <span className="text-sm font-medium text-neutral-900 dark:text-neutral-100">{option.label}</span>
                    <span className="ml-2 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{option.desc}</span>
                  </div>
                </label>
              ))}
            </div>
          </div>

          <div>
            <div className="flex items-center justify-between mb-3">
              <label className="text-sm font-medium text-neutral-700">
                选择列 ({selectedColumns.length}/{columns.length})
              </label>
              <div className="space-x-2">
                <button
                  type="button"
                  onClick={handleSelectAllColumns}
                  disabled={isExporting}
                  className="text-xs text-secondary-600 hover:text-secondary-800"
                >
                  全选
                </button>
                <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">|</span>
                <button
                  type="button"
                  onClick={handleDeselectAllColumns}
                  disabled={isExporting}
                  className="text-xs text-secondary-600 hover:text-secondary-800"
                >
                  全不选
                </button>
              </div>
            </div>
            <div className="max-h-40 overflow-y-auto border border-neutral-200 dark:border-neutral-700 rounded-md p-2 space-y-1">
              {columns.map((col) => (
                <label
                  key={col.key}
                  className={`flex items-center px-2 py-1.5 rounded cursor-pointer hover:bg-neutral-50 dark:bg-neutral-800 ${
                    selectedColumns.includes(col.key) ? 'bg-secondary-50' : ''
                  }`}
                >
                  <input
                    type="checkbox"
                    checked={selectedColumns.includes(col.key)}
                    onChange={() => handleColumnToggle(col.key)}
                    disabled={isExporting}
                    className="w-4 h-4 text-secondary-600 rounded focus:ring-secondary-500"
                  />
                  <span className="ml-2 text-sm text-neutral-700">{col.label}</span>
                </label>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-neutral-700 mb-2">
                文件名
              </label>
              <input
                type="text"
                value={fileName}
                onChange={(e) => setFileName(e.target.value)}
                disabled={isExporting}
                className="w-full px-3 py-2 border border-neutral-300 dark:border-neutral-700 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-secondary-500"
                placeholder="输入文件名..."
              />
            </div>
            <div className="space-y-3 pt-6">
              <label className="flex items-center">
                <input
                  type="checkbox"
                  checked={includeHeader}
                  onChange={(e) => setIncludeHeader(e.target.checked)}
                  disabled={isExporting}
                  className="w-4 h-4 text-secondary-600 rounded focus:ring-secondary-500"
                />
                <span className="ml-2 text-sm text-neutral-700">包含表头</span>
              </label>
              <label className="flex items-center">
                <input
                  type="checkbox"
                  checked={includeIndex}
                  onChange={(e) => setIncludeIndex(e.target.checked)}
                  disabled={isExporting}
                  className="w-4 h-4 text-secondary-600 rounded focus:ring-secondary-500"
                />
                <span className="ml-2 text-sm text-neutral-700">包含序号列</span>
              </label>
            </div>
          </div>
        </div>

        {isExporting && progress && (
          <div className="px-6 py-3 bg-secondary-50 border-t border-secondary-100">
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm font-medium text-secondary-700">{progress.currentStep}</span>
              <span className="text-sm text-secondary-600">
                {progress.progress}/{progress.totalSteps}
              </span>
            </div>
            <div className="w-full bg-secondary-200 rounded-full h-2">
              <div
                className="bg-secondary-600 h-2 rounded-full transition-all duration-300"
                style={{ width: `${(progress.progress / progress.totalSteps) * 100}%` }}
              />
            </div>
          </div>
        )}

        <div className="px-6 py-4 bg-neutral-50 dark:bg-neutral-800 border-t border-neutral-200 flex justify-end space-x-3">
          <button
            onClick={onClose}
            disabled={isExporting}
            className="px-4 py-2 text-sm font-medium text-neutral-700 bg-white dark:bg-neutral-900 border border-neutral-300 rounded-md hover:bg-neutral-50 dark:bg-neutral-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-secondary-500 disabled:opacity-50"
          >
            取消
          </button>
          <button
            onClick={handleExport}
            disabled={isExporting || selectedColumns.length === 0}
            className="px-4 py-2 text-sm font-medium text-secondary-main bg-secondary-container border border-transparent rounded-md hover:bg-secondary-container focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-secondary-500 disabled:opacity-50 disabled:cursor-not-allowed flex items-center"
          >
            {isExporting ? (
              <>
                <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                导出中...
              </>
            ) : (
              <>
                <svg className="-ml-1 mr-2 h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                </svg>
                开始导出
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ExportDialog;

/**
 * 高级筛选器 UI 组件
 *
 * 提供可视化的筛选条件构建界面
 * 支持多条件组合、嵌套分组、保存/加载筛选方案
 */

import { useState, useCallback, useMemo } from 'react';
import type {
  FilterBuilderProps,
  FilterGroup,
  FilterCondition,
  FilterConfig,
  FilterFieldDefinition,
} from '@/types/filter.types';
import {
  FilterOperator,
  OPERATOR_LABELS,
  DEFAULT_OPERATORS_BY_TYPE,
} from '@/types/filter.types';
import { useToast } from '@/components/ui'

function generateFilterId(): string {
  return `${Date.now()}-${Math.random().toString(36).substring(2, 11)}`;
}

function createEmptyFilterGroup(): FilterGroup {
  return {
    id: generateFilterId(),
    logicOperator: 'AND',
    conditions: [],
  };
}

function createEmptyCondition(): FilterCondition {
  return {
    id: generateFilterId(),
    fieldKey: '',
    fieldLabel: '',
    operator: FilterOperator.EQUALS,
    value: '',
  };
}

function cloneFilterGroup(group: FilterGroup): FilterGroup {
  return JSON.parse(JSON.stringify(group));
}

function addCondition(group: FilterGroup): FilterGroup {
  const newGroup = cloneFilterGroup(group);
  newGroup.conditions.push(createEmptyCondition());
  return newGroup;
}

function removeCondition(group: FilterGroup, id: string): FilterGroup {
  const newGroup = cloneFilterGroup(group);
  newGroup.conditions = newGroup.conditions.filter(c => c.id !== id);
  return newGroup;
}

function updateCondition(
  group: FilterGroup,
  id: string,
  updates: Partial<FilterCondition | FilterGroup>,
): FilterGroup {
  const newGroup = cloneFilterGroup(group);

  const updateConditionRecursively = (conditions: (FilterCondition | FilterGroup)[]): (FilterCondition | FilterGroup)[] => {
    return conditions.map(item => {
      if (item.id === id) {
        return { ...item, ...updates };
      }
      if ('conditions' in item) {
        return { ...item, conditions: updateConditionRecursively(item.conditions) };
      }
      return item;
    });
  };

  newGroup.conditions = updateConditionRecursively(newGroup.conditions);
  return newGroup;
}

function countConditions(group: FilterGroup): number {
  let count = 0;
  for (const item of group.conditions) {
    if ('conditions' in item) {
      count += countConditions(item);
    } else {
      count++;
    }
  }
  return count;
}

/**
 * 筛选条件行组件 (单个条件的UI)
 */
function ConditionRow({
  condition,
  fields,
  onChange,
  onRemove,
  depth = 0,
  showLogicOperator = true,
}: {
  condition: FilterCondition;
  fields: FilterFieldDefinition[];
  onChange: (updates: Partial<FilterCondition>) => void;
  onRemove: () => void;
  depth?: number;
  showLogicOperator?: boolean;
}) {
  const selectedField = useMemo(
    () => fields.find(f => f.key === condition.fieldKey),
    [fields, condition.fieldKey],
  );

  const availableOperators = useMemo(() => {
    if (selectedField) {
      return selectedField.operators;
    }
    return DEFAULT_OPERATORS_BY_TYPE.text || [];
  }, [selectedField]);

  const handleFieldChange = useCallback((fieldKey: string) => {
    const field = fields.find(f => f.key === fieldKey);
    if (field) {
      onChange({
        fieldKey: field.key,
        fieldLabel: field.label,
        operator: field.operators[0] || FilterOperator.CONTAINS,
        value: field.defaultValue ?? '',
      });
    }
  }, [fields, onChange]);

  const handleOperatorChange = useCallback((operator: FilterOperator) => {
    // 切换到不需要值的操作符时清空value
    const noValueOps = [FilterOperator.IS_EMPTY, FilterOperator.IS_NOT_EMPTY];
    onChange({
      operator,
      value: noValueOps.includes(operator) ? undefined : condition.value,
    });
  }, [onChange, condition.value]);

  const renderValueInput = () => {
    if (!selectedField ||
        condition.operator === FilterOperator.IS_EMPTY ||
        condition.operator === FilterOperator.IS_NOT_EMPTY) {
      return null;
    }

    switch (selectedField.type) {
      case 'select':
        return (
          <select
            className="w-40 px-2 py-1.5 text-sm border border-neutral-300 rounded-md bg-white dark:bg-neutral-700 dark:border-neutral-600 focus:ring-2 focus:ring-secondary-500 focus:border-transparent"
            value={condition.value ?? ''}
            onChange={(e) => onChange({ value: e.target.value })}
          >
            <option value="">请选择...</option>
            {selectedField.options?.map(opt => (
              <option key={opt.value} value={opt.value}>
                {opt.label}
              </option>
            ))}
          </select>
        );

      case 'number':
        return (
          <input
            type="number"
            className="w-32 px-2 py-1.5 text-sm border border-neutral-300 rounded-md bg-white dark:bg-neutral-700 dark:border-neutral-600 focus:ring-2 focus:ring-secondary-500"
            placeholder={selectedField.placeholder || '输入数值'}
            value={condition.value ?? ''}
            onChange={(e) => onChange({ value: parseFloat(e.target.value) || 0 })}
            min={selectedField.validation?.min}
            max={selectedField.validation?.max}
          />
        );

      case 'date':
        return (
          <input
            type="date"
            className="w-40 px-2 py-1.5 text-sm border border-neutral-300 rounded-md bg-white dark:bg-neutral-700 dark:border-neutral-600 focus:ring-2 focus:ring-secondary-500"
            value={condition.value || ''}
            onChange={(e) => onChange({ value: e.target.value })}
        aria-label={selectedField.label}
      />
        );

      case 'text':
      default:
        return (
          <input
            type="text"
            className="flex-1 px-2 py-1.5 text-sm border border-neutral-300 rounded-md bg-white dark:bg-neutral-700 dark:border-neutral-600 focus:ring-2 focus:ring-secondary-500"
            placeholder={selectedField.placeholder || '输入筛选值...'}
            value={condition.value ?? ''}
            onChange={(e) => onChange({ value: e.target.value })}
          />
        );
    }
  };

  return (
    <div
      className={`flex items-center gap-2 ${depth > 0 ? 'ml-6 pl-4 border-l-2 border-neutral-300 dark:border-neutral-600' : ''}`}
    >
      {/* 逻辑连接符 */}
      {showLogicOperator && (
        <button
          onClick={() => onChange({
            logicOperator: condition.logicOperator === 'AND' ? 'OR' : 'AND',
          })}
          className={`px-2 py-1 text-xs font-medium rounded transition-colors ${
            condition.logicOperator === 'AND'
              ? 'bg-secondary-100 text-secondary-700 dark:bg-secondary-300/25 dark:text-secondary-700'
              : 'bg-warning-100 text-warning-700 dark:bg-warning-300/25 dark:text-warning-700'
          }`}
        >
          {condition.logicOperator}
        </button>
      )}

      {/* 字段选择 */}
      <select
        className="w-36 px-2 py-1.5 text-sm border border-neutral-300 rounded-md bg-white dark:bg-neutral-700 dark:border-neutral-600 focus:ring-2 focus:ring-secondary-500"
        value={condition.fieldKey}
        onChange={(e) => handleFieldChange(e.target.value)}
      >
        <option value="">选择字段...</option>
        {fields.map(field => (
          <option key={field.key} value={field.key}>
            {field.label}
          </option>
        ))}
      </select>

      {/* 操作符选择 */}
      <select
        className="w-28 px-2 py-1.5 text-sm border border-neutral-300 rounded-md bg-white dark:bg-neutral-700 dark:border-neutral-600 focus:ring-2 focus:ring-secondary-500"
        value={condition.operator}
        onChange={(e) => handleOperatorChange(e.target.value as FilterOperator)}
      >
        {availableOperators.map(op => (
          <option key={op} value={op}>
            {OPERATOR_LABELS[op]}
          </option>
        ))}
      </select>

      {/* 值输入 */}
      {renderValueInput()}

      {/* 删除按钮 */}
      <button
        onClick={onRemove}
        className="p-1 text-neutral-400 hover:text-error-600 hover:bg-error-50 dark:hover:bg-error-900/20 rounded transition-colors"
        title="删除此条件"
      >
        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
        </svg>
      </button>
    </div>
  );
}

/**
 * 条件组渲染组件 (递归)
 */
function ConditionGroupRenderer({
  group,
  fields,
  onChange,
  onAddCondition,
  onAddSubGroup,
  onRemoveItem,
  depth = 0,
}: {
  group: FilterGroup;
  fields: FilterFieldDefinition[];
  onChange: (group: FilterGroup) => void;
  onAddCondition: () => void;
  onAddSubGroup: () => void;
  onRemoveItem: (id: string) => void;
  depth?: number;
}) {
  return (
    <div className={`space-y-2 ${depth > 0 ? 'ml-4 p-3 bg-neutral-50 dark:bg-neutral-800/50 rounded-lg' : ''}`}>
      {group.conditions.map((item, index) => {
        if ('conditions' in item) {
          // 嵌套组
          return (
            <div key={item.id} className="relative">
              <div className="flex items-center gap-2 mb-2">
                <span className="text-xs font-medium text-neutral-500 dark:text-neutral-400 px-2 py-1 bg-neutral-200 dark:bg-neutral-700 rounded">
                  条件组 ({item.conditions.length}个条件)
                </span>
                <button
                  onClick={() => onChange(updateCondition(group, item.id, {
                    logicOperator: item.logicOperator === 'AND' ? 'OR' : 'AND',
                  }))}
                  className={`px-2 py-0.5 text-xs font-medium rounded ${
                    item.logicOperator === 'AND'
                      ? 'bg-secondary-100 text-secondary-700'
                      : 'bg-warning-100 text-warning-700'
                  }`}
                >
                  {item.logicOperator}
                </button>
                <button
                  onClick={() => onRemoveItem(item.id)}
                  className="p-0.5 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-error-600 rounded"
                  title="删除条件组"
                >
                  <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
              <ConditionGroupRenderer
                group={item}
                fields={fields}
                onChange={(updatedSubGroup) => {
                  onChange(updateCondition(group, item.id, updatedSubGroup));
                }}
                onAddCondition={() => {} /* 子组的添加由父级处理 */}
                onAddSubGroup={() => {}}
                onRemoveItem={onRemoveItem}
                depth={depth + 1}
              />
            </div>
          );
        } else {
          // 单个条件
          return (
            <ConditionRow
              key={item.id}
              condition={item}
              fields={fields}
              onChange={(updates) => {
                onChange(updateCondition(group, item.id, updates));
              }}
              onRemove={() => onRemoveItem(item.id)}
              depth={depth}
              showLogicOperator={index > 0}
            />
          );
        }
      })}

      {/* 添加按钮 */}
      <div className="flex items-center gap-2 pt-2">
        <button
          onClick={onAddCondition}
          className="inline-flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-secondary-600 bg-secondary-50 hover:bg-secondary-100 dark:bg-secondary-300/20 dark:hover:bg-secondary-900/40 rounded-md transition-colors"
        >
          <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
          </svg>
          添加条件
        </button>

        {depth < 2 && (
          <button
            onClick={onAddSubGroup}
            className="inline-flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-accent-600 bg-accent-50 hover:bg-accent-100 dark:bg-accent-300/20 dark:hover:bg-accent-900/40 rounded-md transition-colors"
          >
            <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
            </svg>
            添加条件组
          </button>
        )}
      </div>
    </div>
  );
}

/**
 * 主筛选器组件
 */
export function FilterBuilder({
  fields,
  value,
  onChange,
  savedFilters = [],
  onSaveFilter,
  onLoadFilter,
  onDeleteFilter,
  maxHeight = 400,
  className = '',
}: FilterBuilderProps) {
  const { error: toastError } = useToast();
  const [filterName, setFilterName] = useState('');
  const [showSavedPanel, setShowSavedPanel] = useState(false);

  const hasConditions = value.conditions.length > 0;

  const handleAddCondition = useCallback(() => {
    const newGroup = addCondition(value);
    onChange(newGroup);
  }, [value, onChange]);

  const handleAddSubGroup = useCallback(() => {
    const newGroup: FilterGroup = {
      ...cloneFilterGroup(value),
      conditions: [
        ...value.conditions,
        {
          id: generateFilterId(),
          logicOperator: 'AND',
          conditions: [],
          level: (value.level || 0) + 1,
        },
      ],
    };
    onChange(newGroup);
  }, [value, onChange]);

  const handleRemoveItem = useCallback((id: string) => {
    const newGroup = removeCondition(value, id);
    onChange(newGroup);
  }, [value, onChange]);

  const handleClearAll = useCallback(() => {
    onChange(createEmptyFilterGroup());
  }, [onChange]);

  const handleSaveCurrentFilter = useCallback(() => {
    if (!filterName.trim()) {
      toastError('请输入筛选方案名称');
      return;
    }

    if (onSaveFilter) {
      onSaveFilter({
        id: generateFilterId(),
        name: filterName.trim(),
        group: cloneFilterGroup(value),
        createdAt: Date.now(),
      });
      setFilterName('');
    }
  }, [filterName, value, onSaveFilter]);

  const handleLoadFilter = useCallback((config: FilterConfig) => {
    if (onLoadFilter) {
      onLoadFilter(config);
    }
  }, [onLoadFilter]);

  return (
    <div className={`bg-white dark:bg-neutral-800 rounded-lg shadow-sm border border-neutral-200 dark:border-neutral-700 ${className}`}>
      {/* 头部工具栏 */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-neutral-200 dark:border-neutral-700">
        <h3 className="text-sm font-semibold text-neutral-800 dark:text-neutral-200">
          🔍 高级筛选
        </h3>

        <div className="flex items-center gap-2">
          {hasConditions && (
            <>
              <span className="text-xs text-neutral-500 dark:text-neutral-400">
                {value.conditions.length} 个条件
              </span>

              <button
                onClick={handleClearAll}
                className="px-2 py-1 text-xs text-error-600 hover:bg-error-50 dark:hover:bg-error-900/20 rounded transition-colors"
              >
                清空
              </button>
            </>
          )}

          {hasConditions && onSaveFilter && (
            <div className="flex items-center gap-1">
              <input
                type="text"
                placeholder="方案名称..."
                value={filterName}
                onChange={(e) => setFilterName(e.target.value)}
                className="w-28 px-2 py-1 text-xs border border-neutral-300 dark:border-neutral-600 rounded bg-white dark:bg-neutral-700"
                onKeyDown={(e) => e.key === 'Enter' && handleSaveCurrentFilter()}
              />
              <button
                onClick={handleSaveCurrentFilter}
                className="px-2 py-1 text-xs font-medium text-success-600 bg-success-50 hover:bg-success-100 dark:bg-success-300/20 rounded transition-colors"
              >
                💾 保存
              </button>
            </div>
          )}
        </div>
      </div>

      {/* 条件列表区域 */}
      <div
        className="overflow-y-auto p-4"
        style={{ maxHeight }}
      >
        {!hasConditions ? (
          <div className="text-center py-8 text-neutral-400 dark:text-neutral-400">
            <svg className="w-12 h-12 mx-auto mb-2 opacity-50" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.364 6.364a1 1 0 00-.293.707V17l-4 4v-2.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" />
            </svg>
            <p className="text-sm">暂无筛选条件</p>
            <p className="text-xs mt-1">点击下方按钮添加筛选条件</p>
          </div>
        ) : (
          <ConditionGroupRenderer
            group={value}
            fields={fields}
            onChange={onChange}
            onAddCondition={handleAddCondition}
            onAddSubGroup={handleAddSubGroup}
            onRemoveItem={handleRemoveItem}
          />
        )}

        {/* 底部添加按钮 (无条件时显示) */}
        {!hasConditions && (
          <div className="mt-4 pt-4 border-t border-dashed border-neutral-300 dark:border-neutral-600">
            <button
              onClick={handleAddCondition}
              className="w-full py-2 text-sm font-medium text-secondary-600 bg-secondary-50 hover:bg-secondary-100 dark:bg-secondary-300/20 dark:hover:bg-secondary-900/40 rounded-lg transition-colors"
            >
              + 添加第一个筛选条件
            </button>
          </div>
        )}
      </div>

      {/* 已保存的筛选方案 */}
      {savedFilters.length > 0 && (
        <div className="border-t border-neutral-200 dark:border-neutral-700">
          <button
            onClick={() => setShowSavedPanel(!showSavedPanel)}
            className="w-full flex items-center justify-between px-4 py-2 text-xs font-medium text-neutral-600 dark:text-neutral-400 hover:bg-neutral-50 dark:hover:bg-neutral-750 transition-colors"
          >
            <span>已保存的方案 ({savedFilters.length})</span>
            <svg
              className={`w-4 h-4 transition-transform ${showSavedPanel ? 'rotate-180' : ''}`}
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
            </svg>
          </button>

          {showSavedPanel && (
            <div className="px-4 pb-3 space-y-1 max-h-40 overflow-y-auto">
              {savedFilters.map(filter => (
                <div
                  key={filter.id}
                  className="flex items-center justify-between px-3 py-2 text-xs bg-neutral-50 dark:bg-neutral-750 rounded hover:bg-neutral-100 dark:hover:bg-neutral-700 transition-colors group"
                >
                  <button
                    onClick={() => handleLoadFilter(filter)}
                    className="flex-1 text-left text-neutral-700 dark:text-neutral-300 truncate"
                  >
                    📋 {filter.name}
                    <span className="ml-2 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                      ({countConditions(filter.group)} 条件)
                    </span>
                  </button>

                  {onDeleteFilter && (
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        onDeleteFilter(filter.id);
                      }}
                      className="opacity-0 group-hover:opacity-100 p-1 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-error-600 transition-all ml-2"
                      title="删除此方案"
                    >
                      <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                      </svg>
                    </button>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default FilterBuilder;

/**
 * ProfessionalReport.tsx - 专业报告预览与导出组件
 *
 * 功能：
 * - 7章节专业报告预览（封面、摘要、配方、成分、协同、建议、附录）
 * - 左侧目录导航 + 右侧内容区域
 * - PDF/Word/Excel多格式导出
 * - 编辑模式支持
 * - 深色模式 + 打印优化
 */

import { logger } from '@/utils/safeLogger'
import React, { useState, useRef, useCallback, useMemo, useEffect } from 'react'
import {
  X, FileText, FileSpreadsheet, Printer,
  Edit3, Check, Loader2, AlertCircle, ChevronRight,
  BookOpen, BarChart3, FlaskConical, Network, Lightbulb,
  Archive, Target, Star, Users, ClipboardList,
} from 'lucide-react'
import type { ReportSection, ReportSectionType } from '@/types/ai.types'
// 导入枚举值和接口（不仅是类型）
import { ExportFormat } from '@/types/ai.types'
import type { ProfessionalReport as ProfessionalReportType } from '@/types/ai.types'
import { FormulaTable } from './FormulaTable'
import { SynergyRadarChart } from './SynergyRadarChart'

// ==================== Types ====================

export interface ProfessionalReportProps {
  report: ProfessionalReportType | null
  isLoading?: boolean
  error?: string | null
  onExport?: (format: ExportFormat) => Promise<void>
  onEdit?: (updates: Partial<ProfessionalReportType>) => void
  onClose?: () => void
  editable?: boolean
}

interface ExportState {
  isExporting: boolean
  format: ExportFormat | null
  progress: number
  error: string | null
}

// ==================== Constants ====================

const SECTION_ICONS: Record<ReportSectionType, React.ReactNode> = {
  'cover': <BookOpen className="w-4 h-4" />,
  'executive-summary': <BarChart3 className="w-4 h-4" />,
  'formula-details': <FlaskConical className="w-4 h-4" />,
  'ingredient-analysis': <Network className="w-4 h-4" />,
  'synergy-assessment': <Network className="w-4 h-4" />,
  'recommendations': <Lightbulb className="w-4 h-4" />,
  'appendix': <Archive className="w-4 h-4" />,
}

const SECTION_TITLES: Record<ReportSectionType, string> = {
  'cover': '封面',
  'executive-summary': '执行摘要',
  'formula-details': '配方详情',
  'ingredient-analysis': '成分分析',
  'synergy-assessment': '协同效果评估',
  'recommendations': '应用建议',
  'appendix': '附录',
}

const EXPORT_FORMAT_CONFIG: Record<ExportFormat, { icon: React.ReactNode; label: string; color: string }> = {
  [ExportFormat.PDF]: { icon: <FileText className="w-4 h-4" />, label: 'PDF', color: 'text-error-600 hover:bg-error-50' },
  [ExportFormat.WORD]: { icon: <FileText className="w-4 h-4" />, label: 'Word', color: 'text-secondary-600 hover:bg-secondary-50' },
  [ExportFormat.EXCEL]: { icon: <FileSpreadsheet className="w-4 h-4" />, label: 'Excel', color: 'text-success-600 hover:bg-success-50' },
  [ExportFormat.CSV]: { icon: <FileSpreadsheet className="w-4 h-4" />, label: 'CSV', color: 'text-accent-600 hover:bg-accent-50' },
  [ExportFormat.JSON]: { icon: <FileText className="w-4 h-4" />, label: 'JSON', color: 'text-warning-600 hover:bg-warning-50' },
}

// ==================== Component ====================

export const ProfessionalReport: React.FC<ProfessionalReportProps> = ({
  report,
  isLoading = false,
  error,
  onExport,
  onEdit,
  onClose,
  editable = false,
}) => {
  // State
  const [isEditing, setIsEditing] = useState(false)
  const [editTitle, setEditTitle] = useState('')
  const [activeSection, setActiveSection] = useState<ReportSectionType>('cover')
  const [exportState, setExportState] = useState<ExportState>({
    isExporting: false,
    format: null,
    progress: 0,
    error: null,
  })

  // Refs
  const contentRef = useRef<HTMLDivElement>(null)
  const sectionRefs = useRef<Record<string, HTMLDivElement | null>>({})

  // Initialize edit title when report changes
  useEffect(() => {
    if (report) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setEditTitle(report.title)
    }
  }, [report?.title])

  // ==================== Handlers ====================

  const handleClose = useCallback(() => {
    if (onClose) onClose()
  }, [onClose])

  const handleToggleEdit = useCallback(() => {
    if (!isEditing && report) {
      setEditTitle(report.title)
    }
    setIsEditing(!isEditing)
  }, [isEditing, report])

  const handleSaveTitle = useCallback(() => {
    if (onEdit && report && editTitle.trim()) {
      onEdit({ ...report, title: editTitle.trim() })
    }
    setIsEditing(false)
  }, [onEdit, report, editTitle])

  const handleScrollToSection = useCallback((sectionType: ReportSectionType) => {
    setActiveSection(sectionType)
    const element = sectionRefs.current[sectionType]
    if (element && contentRef.current) {
      const container = contentRef.current
      const offsetTop = element.offsetTop - container.offsetTop
      container.scrollTo({ top: offsetTop - 20, behavior: 'smooth' })
    }
  }, [])

  const handleExport = useCallback(async (format: ExportFormat) => {
    if (!onExport || exportState.isExporting) return

    setExportState({
      isExporting: true,
      format,
      progress: 0,
      error: null,
    })

    try {
      // Simulate progress
      const progressInterval = setInterval(() => {
        setExportState(prev => ({
          ...prev,
          progress: Math.min(prev.progress + 20, 90),
        }))
      }, 200)

      await onExport(format)

      clearInterval(progressInterval)
      setExportState({
        isExporting: false,
        format: null,
        progress: 100,
        error: null,
      })

      // Reset success state after 3 seconds
      setTimeout(() => {
        setExportState(prev => ({ ...prev, progress: 0 }))
      }, 3000)
    } catch (err) {
      setExportState({
        isExporting: false,
        format: null,
        progress: 0,
        error: err instanceof Error ? err.message : '导出失败',
      })
    }
  }, [onExport, exportState.isExporting])

  const handlePrint = useCallback(() => {
    window.print()
  }, [])

  // ==================== Computed Values ====================

  // eslint-disable-next-line react-hooks/preserve-manual-memoization
  const sortedSections = useMemo(() => {
    if (!report?.sections) return []
    return [...report.sections].sort((a, b) => a.order - b.order)
  }, [report?.sections])

  // ==================== Render Helpers ====================

  const renderSectionContent = (section: ReportSection) => {
    switch (section.type) {
      case 'cover':
        return renderCoverPage()
      case 'executive-summary':
        return renderExecutiveSummary(section)
      case 'formula-details':
        return renderFormulaDetails(section)
      case 'ingredient-analysis':
        return renderIngredientAnalysis(section)
      case 'synergy-assessment':
        return renderSynergyAssessment(section)
      case 'recommendations':
        return renderRecommendations(section)
      case 'appendix':
        return renderAppendix(section)
      default:
        return <div className="p-8 text-center text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">未知章节类型</div>
    }
  }

  const renderCoverPage = () => (
    <div className="min-h-[600px] flex flex-col items-center justify-center bg-gradient-to-br from-secondary-50 to-accent-100 dark:from-neutral-800 dark:to-neutral-900 rounded-lg p-12">
      <div className="text-center space-y-6">
        <h1 className="text-4xl font-bold text-neutral-900 dark:text-white">
          {report?.title || 'RMFOOD 专业分析报告'}
        </h1>
        <div className="w-32 h-1 bg-secondary-600 mx-auto rounded"></div>
        <div className="space-y-2 text-neutral-600 dark:text-neutral-300">
          <p className="text-lg">{report?.metadata?.projectName || '配方研发项目'}</p>
          <p>生成时间：{report?.generatedAt ? new Date(report.generatedAt).toLocaleString('zh-CN') : '-'}</p>
          <p>报告版本：{report?.version || '1.0.0'}</p>
          {report?.metadata?.author && <p>编制：{report.metadata.author}</p>}
        </div>
        <div className="pt-8 text-sm text-neutral-500 dark:text-neutral-400">
          莱茵（厦门）分子生物科技有限公司
        </div>
      </div>
    </div>
  )

  const renderExecutiveSummary = (section: ReportSection) => {
    const content = section.content || {}
    const formulaName = content.formulaName || '待补充'
    const ingredientCount = content.ingredientCount ?? 0
    const sources = content.sources || []
    const totalDosage = content.totalDosage ?? 0
    const keyFindings = content.keyFindings || []
    const recommendationScore = content.recommendationScore ?? 85

    if (process.env.NODE_ENV === 'development') {
