 * - 十八反十九畏禁忌药材预置高亮
 * - 本地分析历史记录（localStorage 持久化）
 * - 快速推荐药材列表（常见配伍组合）
 */

import { useState, useMemo, useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
