export function createMockFormulasArray(count: number): Formula[] {
  const categories = ['功能性成分', '营养强化', '口感改良', '保鲜剂']
  const names = [
    '胶原蛋白肽', '乳清蛋白肽', '海洋鱼肽', '大豆肽', 
