  ]

  return Array.from({ length: count }, (_, i) =>
    createMockFormula({
      name: names[i % names.length] || `自定义配方 ${i + 1}`,
      category: categories[i % categories.length],
      data: {
        ingredients: Array.from({ length: 3 }, (_, j) => ({
          name: `成分 ${j + 1}`,
          percentage: Math.floor(Math.random() * 100),
          unit: '%'
        })),
