/**
 * ErrorRecoveryDialog - 智能错误恢复对话框 (v7.0)
 *
 * 功能特性：
 * 1. 根据错误类型显示差异化的恢复策略和 UI
 * 2. 支持自动重试机制（可配置重试次数）
 * 3. 提供用户友好的错误提示和操作建议
 * 4. 支持倒计时器（限流错误）
 * 5. 可折叠的技术详情面板
 *
 * 错误类型支持：
 * - NetworkTimeout: 网络超时，自动重试3次
 * - Unauthorized: 401未授权，跳转登录
 * - RateLimited: 429限流，倒计时+禁用发送
 * - ServerError: 500服务器错误，指数退避重试
 * - StreamInterrupted: 流式中断，重连选项
 * - Unknown: 未知错误，通用恢复策略
 *
 * @version 7.0.0
 * @lastUpdated 2026-05-11
 */

import React, { useState, useEffect, useCallback, useMemo } from 'react'
import {
  AlertTriangle,
  WifiOff,
  Lock,
  Timer,
  ServerCrash,
  Unplug,
  RefreshCw,
  X,
  LogIn,
  Bug,
  Lightbulb,
} from 'lucide-react'
import { Button } from '@/components/ui'
import { logger } from '@/utils/safeLogger'

export enum ErrorType {
  NetworkTimeout = 'network_timeout',
  NetworkUnreachable = 'network_unreachable',
  Unauthorized = 'unauthorized',
  Forbidden = 'forbidden',
  RateLimited = 'rate_limited',
  ServerError = 'server_error',
  StreamInterrupted = 'stream_interrupted',
  Unknown = 'unknown',
}

interface ClassifiedError {
  type: ErrorType
  originalError: Error
  userMessage: string
  suggestion: string
  canAutoRecover: boolean
  retryAfter?: number
  countdown?: number
}

export interface ErrorRecoveryDialogProps {
  error: Error | null
  errorType?: ErrorType
  onRetry?: () => Promise<void>
  onDismiss?: () => void
  onLogin?: () => void
  autoRetryCount?: number
  showDetails?: boolean
  className?: string
}

const ERROR_CONFIG: Record<ErrorType, {
  icon: React.ComponentType<any>
  title: string
  colorClass: string
  bgClass: string
}> = {
  [ErrorType.NetworkTimeout]: {
    icon: WifiOff,
    title: '连接超时',
    colorClass: 'text-warning-600 dark:text-warning-700',
    bgClass: 'bg-warning-100 dark:bg-warning-300/25',
  },
  [ErrorType.NetworkUnreachable]: {
    icon: WifiOff,
    title: '无法连接服务',
    colorClass: 'text-error-600 dark:text-error-600',
    bgClass: 'bg-error-100 dark:bg-error-300/25',
  },
  [ErrorType.Unauthorized]: {
    icon: Lock,
    title: '会话已过期',
    colorClass: 'text-error-600 dark:text-error-600',
    bgClass: 'bg-error-100 dark:bg-error-300/25',
  },
  [ErrorType.Forbidden]: {
    icon: Lock,
    title: '权限不足',
    colorClass: 'text-error-600 dark:text-error-600',
    bgClass: 'bg-error-100 dark:bg-error-300/25',
  },
  [ErrorType.RateLimited]: {
    icon: Timer,
    title: '请求过于频繁',
    colorClass: 'text-warning-600 dark:text-warning-700',
    bgClass: 'bg-warning-100 dark:bg-warning-300/25',
  },
  [ErrorType.ServerError]: {
    icon: ServerCrash,
    title: '服务器繁忙',
    colorClass: 'text-accent-600 dark:text-accent-700',
    bgClass: 'bg-accent-100 dark:bg-accent-300/25',
  },
  [ErrorType.StreamInterrupted]: {
    icon: Unplug,
    title: '响应中断',
    colorClass: 'text-secondary-600 dark:text-secondary-700',
    bgClass: 'bg-secondary-100 dark:bg-secondary-300/25',
  },
  [ErrorType.Unknown]: {
    icon: AlertTriangle,
    title: '发生错误',
    colorClass: 'text-neutral-600 dark:text-neutral-400',
    bgClass: 'bg-neutral-100 dark:bg-neutral-900/30',
  },
}

const SUGGESTIONS: Record<ErrorType, string> = {
  [ErrorType.NetworkTimeout]: '请检查您的网络连接后重试',
  [ErrorType.NetworkUnreachable]: 'AI 服务暂时不可用，请确认后端服务已启动 (端口 8000)',
  [ErrorType.Unauthorized]: '请重新登录以继续使用',
  [ErrorType.Forbidden]: '您的账号没有访问 AI 服务的权限，请联系管理员',
  [ErrorType.RateLimited]: '请稍等片刻后再发送消息',
  [ErrorType.ServerError]: '我们正在努力修复，请稍后重试',
  [ErrorType.StreamInterrupted]: '网络连接不稳定，是否重新生成响应？',
  [ErrorType.Unknown]: '请稍后重试或联系客服获取帮助',
}

function classifyError(error: Error): ClassifiedError {
  const errorMessage = error.message.toLowerCase()
  const errorName = error.name

  // ── 网络不可达：后端未启动 / 代理连接失败 / fetch 本身失败 ──
  const isNetworkUnreachable =
    errorMessage.includes('failed to fetch') ||
    errorMessage.includes('err_aborted') ||
    errorMessage.includes('aborted') ||
    errorMessage.includes('networkerror') ||
    (errorName === 'TypeError' && (errorMessage.includes('fetch') || errorMessage.includes('network')))

  if (isNetworkUnreachable) {
    return {
      type: ErrorType.NetworkUnreachable,
      originalError: error,
      userMessage: '无法连接到 AI 服务，请检查后端服务是否已启动',
      suggestion: SUGGESTIONS[ErrorType.NetworkUnreachable],
      canAutoRecover: true,
      retryAfter: 3000,
    }
  }

  if (errorName === 'TimeoutError' || errorMessage.includes('timeout')) {
    return {
      type: ErrorType.NetworkTimeout,
      originalError: error,
      userMessage: '网络连接超时，正在尝试重新连接...',
      suggestion: SUGGESTIONS[ErrorType.NetworkTimeout],
      canAutoRecover: true,
      retryAfter: 1000,
    }
  }

  if (
    errorMessage.includes('401') ||
    errorMessage.includes('unauthorized') ||
    errorMessage.includes('认证失败')
  ) {
    return {
      type: ErrorType.Unauthorized,
      originalError: error,
      userMessage: '您的登录会话已过期',
      suggestion: SUGGESTIONS[ErrorType.Unauthorized],
      canAutoRecover: false,
    }
  }

  if (errorMessage.includes('429') || errorMessage.includes('请求过于频繁') || errorMessage.includes('rate limit')) {
    const countdownMatch = /剩余\s*(\d+)/.exec(error.message)
    const countdown = countdownMatch ? parseInt(countdownMatch[1]) : 60

    return {
      type: ErrorType.RateLimited,
      originalError: error,
      userMessage: `请求过于频繁，请等待 ${countdown}s`,
      suggestion: SUGGESTIONS[ErrorType.RateLimited],
      canAutoRecover: false,
      countdown,
    }
  }

  if (
    errorMessage.includes('500') ||
    errorMessage.includes('服务器错误') ||
    errorMessage.includes('server error')
  ) {
    return {
      type: ErrorType.ServerError,
      originalError: error,
      userMessage: '服务器暂时无法处理请求',
      suggestion: SUGGESTIONS[ErrorType.ServerError],
      canAutoRecover: true,
      retryAfter: 2000,
    }
  }

  // 403 权限不足
  if (errorMessage.includes('403') || errorMessage.includes('forbidden') || errorMessage.includes('权限')) {
    return {
      type: ErrorType.Forbidden,
      originalError: error,
      userMessage: '权限不足，请重新登录后重试',
      suggestion: SUGGESTIONS[ErrorType.Forbidden],
      canAutoRecover: false,
    }
  }

  if (
    errorMessage.includes('流式') ||
    errorMessage.includes('stream') ||
    errorMessage.includes('中断')
  ) {
    return {
      type: ErrorType.StreamInterrupted,
      originalError: error,
      userMessage: 'AI 响应在传输过程中被中断',
      suggestion: SUGGESTIONS[ErrorType.StreamInterrupted],
      canAutoRecover: true,
      retryAfter: 500,
    }
  }

  return {
    type: ErrorType.Unknown,
    originalError: error,
    userMessage: '发生了未知错误',
    suggestion: SUGGESTIONS[ErrorType.Unknown],
    canAutoRecover: true,
    retryAfter: 2000,
  }
}

export function ErrorRecoveryDialog({
  error,
  errorType: propErrorType,
  onRetry,
  onDismiss,
  onLogin,
  autoRetryCount = 3,
  showDetails = false,
  className = '',
}: ErrorRecoveryDialogProps) {
  const [retryCount, setRetryCount] = useState(0)
  const [isRetrying, setIsRetrying] = useState(false)
  const [countdown, setCountdown] = useState(0)
  const [autoRetryExhausted, setAutoRetryExhausted] = useState(false)

  const classifiedError = useMemo(() => {
    if (!error) return null
    const classified = classifyError(error)
    return propErrorType ? { ...classified, type: propErrorType } : classified
  }, [error, propErrorType])

  useEffect(() => {
    if (classifiedError?.type !== ErrorType.RateLimited || !classifiedError.countdown) {
      return
    }

    // eslint-disable-next-line react-hooks/set-state-in-effect
    setCountdown(classifiedError.countdown)
    const timer = setInterval(() => {
      setCountdown(prev => {
        if (prev <= 1) {
          clearInterval(timer)
          return 0
        }
        return prev - 1
      })
    }, 1000)

    return () => clearInterval(timer)
  }, [classifiedError])

  useEffect(() => {
    if (!classifiedError || !classifiedError.canAutoRecover || !onRetry || autoRetryExhausted) {
      return
    }

    const attemptAutoRetry = async () => {
      for (let i = 0; i < autoRetryCount; i++) {
        if (!classifiedError?.canAutoRecover) break

        await new Promise(resolve => setTimeout(resolve, classifiedError.retryAfter || 1000))

        try {
          setIsRetrying(true)
          setRetryCount(prev => prev + 1)
          logger.info(`[ErrorRecoveryDialog] 自动重试第 ${i + 1}/${autoRetryCount} 次`)
          await onRetry()
          logger.info('[ErrorRecoveryDialog] 自动重试成功')
          return
        } catch (retryError) {
          logger.warn(`[ErrorRecoveryDialog] 自动重试第 ${i + 1} 次失败:`, retryError)
          if (i === autoRetryCount - 1) {
            setAutoRetryExhausted(true)
          }
        } finally {
          setIsRetrying(false)
        }
      }
    }

    attemptAutoRetry()
  }, [classifiedError, onRetry, autoRetryCount, autoRetryExhausted])

  const handleRetry = useCallback(async () => {
    if (!onRetry || isRetrying) return

    try {
      setIsRetrying(true)
      setRetryCount(prev => prev + 1)
      logger.info('[ErrorRecoveryDialog] 用户手动重试')
      await onRetry()
    } catch (retryError) {
      logger.error('[ErrorRecoveryDialog] 手动重试失败:', retryError)
    } finally {
      setIsRetrying(false)
    }
  }, [onRetry, isRetrying])

  const handleLogin = useCallback(() => {
    logger.info('[ErrorRecoveryDialog] 用户点击登录')
    onLogin?.()
  }, [onLogin])

  const handleDismiss = useCallback(() => {
    logger.info('[ErrorRecoveryDialog] 用户关闭错误提示')
    onDismiss?.()
  }, [onDismiss])

  if (!error || !classifiedError) {
    return null
  }

  const config = ERROR_CONFIG[classifiedError.type]
  const IconComponent = config.icon
  const canShowRetry =
    classifiedError.canAutoRecover &&
    (autoRetryExhausted || retryCount >= autoRetryCount)

  return (
    <div className={`error-recovery-dialog rounded-lg border p-6 shadow-lg ${className}`}>
      <div className="flex items-start gap-4">
        <div className={`flex-shrink-0 w-12 h-12 rounded-full ${config.bgClass} flex items-center justify-center`}>
          <IconComponent className={`w-6 h-6 ${config.colorClass}`} />
        </div>

        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between mb-2">
            <h3 className="text-lg font-semibold text-neutral-900 dark:text-white">
              {config.title}
            </h3>
            <button
              onClick={handleDismiss}
              className="flex-shrink-0 ml-2 text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-300"
              aria-label="关闭"
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          <p className="text-sm text-neutral-700 dark:text-neutral-300 mb-3">
            {classifiedError.userMessage}
          </p>

          <div className="flex items-start gap-2 mb-4 text-sm text-neutral-600 dark:text-neutral-400">
            <Lightbulb className="w-4 h-4 mt-0.5 flex-shrink-0" />
            <span>{classifiedError.suggestion}</span>
          </div>

          <div className="flex flex-wrap items-center gap-3">
            {(classifiedError.type === ErrorType.Unauthorized || classifiedError.type === ErrorType.Forbidden) && onLogin && (
              <Button
                variant="primary"
                size="sm"
                onClick={handleLogin}
                className="inline-flex items-center gap-2"
              >
                <LogIn className="w-4 h-4" />
                重新登录
              </Button>
            )}

            {classifiedError.type === ErrorType.RateLimited && countdown > 0 && (
              <Button variant="outline" size="sm" disabled className="inline-flex items-center gap-2">
                <Timer className="w-4 h-4" />
                等待 {countdown}s
              </Button>
            )}

            {canShowRetry && (
              <Button
                variant="outline"
                size="sm"
                onClick={handleRetry}
                disabled={isRetrying}
                className="inline-flex items-center gap-2"
              >
                <RefreshCw className={`w-4 h-4 ${isRetrying ? 'animate-spin' : ''}`} />
                {isRetrying ? '重试中...' : `重试 (${retryCount}/${autoRetryCount})`}
              </Button>
            )}

            <Button
              variant="ghost"
              size="sm"
              onClick={handleDismiss}
              className="inline-flex items-center gap-2"
            >
              关闭
            </Button>
          </div>

          {showDetails && (
            <details className="mt-4 text-left">
              <summary className="cursor-pointer text-xs font-medium text-neutral-500 dark:text-neutral-400 hover:text-neutral-700 dark:hover:text-neutral-300 inline-flex items-center gap-1">
                <Bug className="w-3 h-3" />
                技术详情
              </summary>
              <pre className="mt-2 p-3 bg-neutral-50 dark:bg-neutral-800 rounded-lg text-xs text-error-600 dark:text-error-600 overflow-auto max-h-40 whitespace-pre-wrap">
                {classifiedError.originalError.message}
                {'\n\n'}
                {classifiedError.originalError.stack}
              </pre>
            </details>
          )}
        </div>
      </div>
    </div>
  )
}

export default ErrorRecoveryDialog

/**
 * FormulaPanel - 配方列表面板组件 (v8.0)
 *
 * 职责：展示AI识别的配方列表，提供搜索、高级筛选、排序、查看详情、操作和导入/导出等功能。
 *
 * 核心功能模块：
 * 1. 面板头部 - 专业级设计（图标+标题+统计徽章+生成报告按钮）
 * 2. 提示文本区域 - 蓝色背景的使用说明
 * 3. 智能搜索栏 - 支持中文/拼音/英文模糊搜索（200ms debounce）
 * 4. 排序控制栏 - 6种排序维度 × 2种方向
 * 5. 高级筛选器 - 多条件组合筛选（质量等级/置信度/时间范围/成分数量/标签）
 * 6. 配方列表 - 使用 FormulaCard 组件的专业卡片展示
 * 7. 批量操作栏 - 条件渲染的选中项操作区
 * 8. 分页控件 - 大数据量优化（默认每页10条）
 * 9. 工具栏 - 导入/导出多格式/清除存储
 *
 * @version 8.0.0
 * @lastUpdated 2026-05-20
 * @author RMFOOD Team (Advanced Search & Filter Enhancement)
 */

import React, { useState, useCallback, useMemo, useRef, useEffect } from 'react'
import type { AIRecognizedFormula, FormulaQualityScore, FormulaFilters, FormulaSortField, SortOrder } from '@/types/ai.types'
import { Button } from '@/components/ui'
import { cn } from '@/lib/utils'
import { FormulaCard } from './FormulaCard'
import { FormulaSkeleton } from './FormulaSkeleton'
import { AdvancedFilter } from './AdvancedFilter'
import { MobileBottomSheet } from '@/hooks/components/MobileBottomSheet'
import { smartMatch } from '@/utils/pinyinUtils'
import '@/styles/animations.css'

import {
  FlaskConical,
  X,
  FileText,
  Loader2,
  Search,
  ArrowUpDown,
  SlidersHorizontal,
  LayoutGrid,
  MoreVertical,
  Eye,
} from 'lucide-react'

/** 分页配置常量 */
const ITEMS_PER_PAGE = 10

/** 上下文菜单状态接口 */
interface ContextMenuState {
  isOpen: boolean
  formulaId: string | null
  position: { x: number; y: number }
}


/**
 * 支持中文/拼音/英文混合模糊搜索
 * @param keyword - 搜索关键词
 * @param formula - 配方对象
 * @returns 是否匹配
 */
function matchFormula(keyword: string, formula: AIRecognizedFormula): boolean {
  if (!keyword.trim()) return true

  const searchText = `${formula.autoName || formula.name || ''} ${formula.efficacy || ''} ${(formula.tags || []).join(' ')}`.toLowerCase()
  const kw = keyword.toLowerCase().trim()

  if (searchText.includes(kw)) return true

  if (smartMatch(formula.autoName || formula.name || '', kw)) return true

  if (formula.efficacy && smartMatch(formula.efficacy, kw)) return true

  if (formula.tags?.some(tag => smartMatch(tag, kw))) return true

  if (formula.ingredients?.some(ing => smartMatch(ing.name || '', kw))) return true

  return false
}

/**
 * 配方列表面板的属性接口 (v8.0 增强版)
 */
interface FormulaPanelProps {
  /** 原始配方列表（未过滤） */
  formulas: AIRecognizedFormula[]
  /** 配方总数 */
  formulaCount: number
  /** 已展开的配方ID集合 */
  expandedIds: Set<string>
  /** 已选中的配方ID集合（用于批量操作） */
  selectedIds: Set<string>
  /** 当前搜索关键词 */
  searchQuery: string
  /** 搜索关键词变更回调 */
  onSearchChange?: (query: string) => void
  /** 当前筛选条件 */
  filters?: FormulaFilters
  /** 筛选条件变更回调 */
  onFiltersChange?: (filters: FormulaFilters) => void
  /** 当前排序字段 */
  sortBy?: FormulaSortField
  /** 当前排序方向 */
  sortOrder?: SortOrder
  /** 排序变更回调 */
  onSortChange?: (field: FormulaSortField, order: SortOrder) => void
  /** 切换配方展开状态 */
  onToggleExpand: (id: string) => void
  /** 切换配方选中状态 */
  onToggleSelect: (id: string) => void
  /** 查看详细数据表格 */
  onShowDetail: (id: string) => void
  /** 生成专业报告（可选指定单个配方） */
  onGenerateReport: (id?: string) => void
  /** 重命名配方 */
  onRenameFormula?: (id: string, newName: string) => void
  /** 获取配方质量评分 */
  getFormulaScore?: (id: string) => FormulaQualityScore | null | undefined
  /** 导出数据（支持多种格式） */
  onExport: (format: string) => void
  /** 从文件导入数据 */
  onImport: () => void
  /** 清除本地存储的所有配方数据 */
  onClearStorage: () => void
  /** 清空内存中的配方缓存 */
  onClearMemory: () => void
  /** 删除配方（带动画） */
  onRemoveFormula?: (id: string) => void
  /** 清空选中状态 */
  clearSelection?: () => void
  /** 报告生成加载状态 */
  isGeneratingReport: boolean
  /** 配方数据加载状态（用于显示骨架屏） */
  isLoading?: boolean
  /** 关闭面板事件处理 */
  onClose: () => void
  /** 批量导出 */
  onBatchExport?: (format: 'json' | 'csv' | 'excel' | 'pdf') => void
  /** 批量删除 */
  onBatchDelete?: (ids: string[]) => void
  /** 批量打标签 */
  onBatchTag?: (ids: string[], tags: string[]) => void
  /** 全选 */
  onSelectAll?: () => void
}

/**
 * FormulaPanel - 配方列表面板组件 (v8.0)
 *
 * 使用 React.memo 进行性能优化，避免不必要的重新渲染。
 * 内置搜索、筛选、排序逻辑，减少父组件负担。
 */
const FormulaPanel = React.memo<FormulaPanelProps>(({
  formulas,
  formulaCount,
  expandedIds,
  selectedIds,
  searchQuery,
  onSearchChange,
  filters: externalFilters,
  onFiltersChange,
  sortBy: externalSortBy,
  sortOrder: externalSortOrder,
  onSortChange,
  onToggleExpand,
  onToggleSelect,
  onShowDetail,
  onGenerateReport,
  onRenameFormula,
  getFormulaScore,
  onExport,
  onImport,
  onClearStorage,
  onClearMemory,
  onRemoveFormula,
  clearSelection,
  isGeneratingReport,
  isLoading,
  onClose,
}) => {

  const [localSearchQuery, setLocalSearchQuery] = useState(searchQuery)
  const [showAdvancedFilter, setShowAdvancedFilter] = useState(false)
  const [localSortBy, setLocalSortBy] = useState<FormulaSortField>(externalSortBy || 'createdAt')
  const [localSortOrder, setLocalSortOrder] = useState<SortOrder>(externalSortOrder || 'desc')
  const [currentPage, setCurrentPage] = useState(1)
  const [, setDeletingIds] = useState<Set<string>>(new Set())
  const [isTabletView, setIsTabletView] = useState(false)
  const [showMoreMenu, setShowMoreMenu] = useState(false)
  const [contextMenu, setContextMenu] = useState<ContextMenuState>({
    isOpen: false,
    formulaId: null,
    position: { x: 0, y: 0 },
  })
  const searchInputRef = useRef<HTMLInputElement>(null)
  const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => {
    setLocalSearchQuery(searchQuery)
  }, [searchQuery])

  useEffect(() => {
    if (externalSortBy) setLocalSortBy(externalSortBy)
  }, [externalSortBy])

  useEffect(() => {
    if (externalSortOrder) setLocalSortOrder(externalSortOrder)
  }, [externalSortOrder])

  /**
   * 搜索关键词变更处理（带200ms防抖）
   */
  const handleSearchChange = useCallback((value: string) => {
    setLocalSearchQuery(value)

    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current)
    }

    debounceTimerRef.current = setTimeout(() => {
      onSearchChange?.(value)
      setCurrentPage(1)
    }, 200)
  }, [onSearchChange])

  /**
   * 清除搜索
   */
  const handleClearSearch = useCallback(() => {
    setLocalSearchQuery('')
    onSearchChange?.('')
    setCurrentPage(1)
    searchInputRef.current?.focus()
  }, [onSearchChange])

  /**
   * 排序字段变更
   */
  const handleSortChange = useCallback((field: FormulaSortField) => {
    const newOrder = field === localSortBy && localSortOrder === 'asc' ? 'desc' : 'asc'
    setLocalSortBy(field)
    setLocalSortOrder(newOrder)
    onSortChange?.(field, newOrder)
    setCurrentPage(1)
  }, [localSortBy, localSortOrder, onSortChange])

  /**
   * 切换排序方向
   */
  const toggleSortOrder = useCallback(() => {
    const newOrder = localSortOrder === 'asc' ? 'desc' : 'asc'
    setLocalSortOrder(newOrder)
    onSortChange?.(localSortBy, newOrder)
    setCurrentPage(1)
  }, [localSortBy, localSortOrder, onSortChange])

  /**
   * 应用搜索、筛选和排序的优化结果（使用 useMemo 缓存）
   */
  const filteredAndSortedFormulas = useMemo(() => {
    let result = [...formulas]

    if (localSearchQuery.trim()) {
      result = result.filter(f => matchFormula(localSearchQuery, f))
    }

    if (externalFilters) {
      if (externalFilters.qualityGrades && externalFilters.qualityGrades.length > 0) {
        result = result.filter(f => f.qualityGrade && externalFilters.qualityGrades!.includes(f.qualityGrade))
      }

      if (externalFilters.confidenceRange) {
        const { min, max } = externalFilters.confidenceRange
        result = result.filter(f => {
          const confidencePercent = Math.round(f.confidence * 100)
          return confidencePercent >= min && confidencePercent <= max
        })
      }

      if (externalFilters.dateRange) {
        const { start, end } = externalFilters.dateRange
        result = result.filter(f => {
          const createdAt = f.createdAt || (f.parsedAt instanceof Date ? f.parsedAt.getTime() : Date.now())
          return createdAt >= start && createdAt <= end
        })
      }

      if (externalFilters.ingredientCountRange) {
        const { min, max } = externalFilters.ingredientCountRange
        result = result.filter(f => f.ingredientCount >= min && f.ingredientCount <= max)
      }

      if (externalFilters.tags && externalFilters.tags.length > 0) {
        result = result.filter(f =>
          f.tags?.some(tag => externalFilters.tags!.includes(tag)),
        )
      }
    }

    result.sort((a, b) => {
      let comparison = 0

      switch (localSortBy) {
        case 'createdAt':
          comparison = (a.createdAt || 0) - (b.createdAt || 0)
          break
        case 'updatedAt':
          comparison = (a.updatedAt || 0) - (b.updatedAt || 0)
          break
        case 'name':
          comparison = (a.autoName || a.name || '').localeCompare(b.autoName || b.name || '')
          break
        case 'confidence':
          comparison = a.confidence - b.confidence
          break
        case 'qualityScore':
          comparison = (a.qualityScore || 0) - (b.qualityScore || 0)
          break
        case 'ingredientCount':
          comparison = a.ingredientCount - b.ingredientCount
          break
        default:
          comparison = 0
      }

      return localSortOrder === 'asc' ? comparison : -comparison
    })

    return result
  }, [formulas, localSearchQuery, externalFilters, localSortBy, localSortOrder])

  const totalPages = useMemo(() => Math.ceil(filteredAndSortedFormulas.length / ITEMS_PER_PAGE), [filteredAndSortedFormulas.length])

  const paginatedFormulas = useMemo(() => {
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE
    const endIndex = startIndex + ITEMS_PER_PAGE
    return filteredAndSortedFormulas.slice(startIndex, endIndex)
  }, [filteredAndSortedFormulas, currentPage])

  const loadPrevPage = useCallback(() => {
    setCurrentPage(prev => Math.max(1, prev - 1))
  }, [])

  const loadNextPage = useCallback(() => {
    setCurrentPage(prev => Math.min(totalPages, prev + 1))
  }, [totalPages])

  const handleFiltersChange = useCallback((newFilters: FormulaFilters) => {
    onFiltersChange?.(newFilters)
    setCurrentPage(1)
  }, [onFiltersChange])

  const handleResetFilters = useCallback(() => {
    handleClearSearch()
    onFiltersChange?.({})
    setShowAdvancedFilter(false)
  }, [handleClearSearch, onFiltersChange])

  const handleShowContextMenu = useCallback((formulaId: string, position: { x: number; y: number }) => {
    setContextMenu({
      isOpen: true,
      formulaId,
      position,
    })
  }, [])

  const handleCloseContextMenu = useCallback(() => {
    setContextMenu(prev => ({ ...prev, isOpen: false }))
  }, [])

  /**
   * 带退场动画的删除处理 (提前定义以避免TDZ错误)
   */
  const handleDeleteWithAnimation = useCallback(async (id: string) => {
    setDeletingIds(prev => new Set([...prev, id]))

    await new Promise(resolve => setTimeout(resolve, 300))

    onRemoveFormula?.(id)
    setDeletingIds(prev => {
      const next = new Set(prev)
      next.delete(id)
      return next
    })
  }, [])

  const handleContextAction = useCallback((action: string) => {
    if (!contextMenu.formulaId) return

    switch (action) {
      case 'viewDetail':
        onShowDetail(contextMenu.formulaId)
        break
      case 'generateReport':
        onGenerateReport(contextMenu.formulaId)
        break
      case 'export':
        onExport('json')
        break
      case 'delete':
        handleDeleteWithAnimation(contextMenu.formulaId)
        break
    }

    handleCloseContextMenu()
  }, [contextMenu.formulaId, onShowDetail, onGenerateReport, handleDeleteWithAnimation, handleCloseContextMenu])

  const activeFilterCount = useMemo(() => {
    if (!externalFilters) return 0

    let count = 0
    if (externalFilters.qualityGrades && externalFilters.qualityGrades.length > 0) count++
    if (externalFilters.confidenceRange) count++
    if (externalFilters.dateRange) count++
    if (externalFilters.ingredientCountRange) count++
    if (externalFilters.tags && externalFilters.tags.length > 0) count++

    return count
  }, [externalFilters])

  return (
    <div className="fixed inset-0 z-50 bg-black/50 flex items-end justify-end p-4"
          role="button" tabIndex={0} onClick={(e) => {
           if (e.target === e.currentTarget) onClose()
         }}>
      <div
        className="bg-white dark:bg-neutral-800 rounded-xl shadow-2xl w-full max-w-2xl max-h-[85vh] overflow-hidden
                   flex flex-col animate-in-from-right"
         role="button" tabIndex={0} onClick={e => e.stopPropagation()}
      >
        {/* ===== 面板头部区域 - 移动端自适应 ===== */}
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 px-4 py-3 sm:px-6 sm:py-4 border-b border-neutral-200 dark:border-neutral-700 bg-gradient-to-r from-neutral-50 to-white dark:from-neutral-800 dark:to-neutral-900">
          <div className="flex items-center gap-2 sm:gap-3 w-full sm:w-auto">
            <FlaskConical className="w-5 h-5 sm:w-6 sm:h-6 text-primary-700 shrink-0" />
            <h2 className="text-base sm:text-xl font-bold text-neutral-900 dark:text-white">
              已识别的配方
            </h2>
            <span className="px-2 py-0.5 sm:px-3 sm:py-1 rounded-full text-xs sm:text-sm font-semibold bg-primary-100 text-primary-700 dark:bg-primary-300/25 dark:text-primary-700">
              {filteredAndSortedFormulas.length}/{formulaCount}
            </span>
          </div>

          <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2 w-full sm:w-auto">
            <Button
              onClick={() => onGenerateReport()}
              disabled={isGeneratingReport || formulaCount === 0}
              className="w-full sm:w-auto bg-primary-container text-primary-main shadow-lg px-4 py-2.5 sm:py-2 rounded-lg font-medium transition-all duration-200 hover:scale-105 active:scale-95"
              icon={isGeneratingReport ? <Loader2 size={16} className="animate-spin" /> : <FileText size={16} />}
            >
              {isGeneratingReport ? '生成中...' : `生成报告 (${formulaCount})`}
            </Button>

            {/* 平板端视图切换按钮 */}
            <button
              onClick={() => setIsTabletView(!isTabletView)}
              className="hidden md:flex lg:hidden items-center justify-center gap-2 px-3 py-2 rounded-lg hover:bg-neutral-100 dark:bg-neutral-800 dark:hover:bg-neutral-800 transition-colors min-h-[44px]"
              title={isTabletView ? '切换到单列视图' : '切换到双列视图'}
            >
              <LayoutGrid className="w-4 h-4" />
              <span className="text-sm">{isTabletView ? '单列' : '双列'}</span>
            </button>

            <button
              onClick={onClose}
              className="self-end sm:self-auto p-2 -mr-2 sm:mr-0 rounded-lg hover:bg-neutral-100 dark:bg-neutral-800 dark:hover:bg-neutral-800 transition-colors min-h-[44px] min-w-[44px] sm:min-h-0 sm:min-w-0"
              aria-label="关闭面板"
            >
              <X className="w-5 h-5 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
            </button>
          </div>
        </div>

        {/* 提示文本区域 */}
        <div className="px-6 py-2 text-sm text-secondary-700 dark:text-secondary-700 bg-secondary-50 dark:bg-secondary-300/20 border-b border-secondary-100 dark:border-secondary-900/30">
          支持中文/拼音/英文智能搜索 · 多条件组合筛选 · 多维度排序
        </div>

        {/* ===== 搜索框区域 ===== */}
        <div className="p-4 border-b border-neutral-200 dark:border-neutral-700">
          <div className="flex items-center gap-2">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
              <input
                ref={searchInputRef}
                type="text"
                placeholder="🔍 搜索配方（支持拼音/中文/英文）..."
                value={localSearchQuery}
                onChange={(e) => handleSearchChange(e.target.value)}
                className="w-full pl-10 pr-10 py-2.5 border border-neutral-300 dark:border-neutral-600 rounded-lg
                         bg-neutral-50 dark:bg-neutral-900 text-sm focus:ring-2 focus:ring-secondary-500
                         focus:border-transparent outline-none transition-all"
              />
              {localSearchQuery && (
                <button
                  onClick={handleClearSearch}
                  className="absolute right-3 top-1/2 transform -translate-y-1/2 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-neutral-600"
                >
                  ✕
                </button>
              )}
            </div>

            <Button
              variant={showAdvancedFilter ? "primary" : "outline"}
              size="sm"
              onClick={() => setShowAdvancedFilter(!showAdvancedFilter)}
              icon={<SlidersHorizontal size={16} />}
              className="relative"
            >
              <span className="hidden sm:inline">高级筛选</span>
              <span className="sm:hidden">筛选</span>
              {activeFilterCount > 0 && (
                <span className="absolute -top-1 -right-1 w-5 h-5 bg-error-500 text-white text-xs rounded-full flex items-center justify-center">
                  {activeFilterCount}
                </span>
              )}
            </Button>
          </div>

          {localSearchQuery && (
            <div className="mt-2 text-xs text-neutral-500 dark:text-neutral-400">
              🔍 搜索 "<strong>{localSearchQuery}</strong>" · 找到 <strong>{filteredAndSortedFormulas.length}</strong> 个匹配结果
            </div>
          )}
        </div>

        {/* ===== 高级筛选器 - 移动端/平板端使用侧滑抽屉 ===== */}
        <MobileBottomSheet
          open={showAdvancedFilter}
          onClose={() => setShowAdvancedFilter(false)}
          title="高级筛选"
        >
          <AdvancedFilter
            filters={externalFilters || {}}
            onFiltersChange={handleFiltersChange}
            onReset={handleResetFilters}
            allFormulas={formulas}
          />
        </MobileBottomSheet>

        {/* ===== 排序控制栏 ===== */}
        <div className="flex items-center gap-4 px-6 py-3 bg-neutral-50 dark:bg-neutral-800 text-sm border-b border-neutral-200 dark:border-neutral-700">
          <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] flex items-center gap-1">
            <ArrowUpDown size={14} />
            排序:
          </span>

          <select
            value={localSortBy}
            onChange={(e) => handleSortChange(e.target.value as FormulaSortField)}
            className="px-3 py-1.5 rounded-md border border-neutral-300 dark:border-neutral-600 bg-white dark:bg-neutral-700 text-sm focus:ring-2 focus:ring-secondary-500 outline-none"
          >
            <option value="createdAt">创建时间</option>
            <option value="updatedAt">更新时间</option>
