/**
 * 建议质量评估反馈闭环系统 V4.0
 *
 * 核心特性：
 * - 多维度质量评分（相关性、新颖性、可操作性、证据强度）
 * - 用户行为追踪与分析（点击、采纳、忽略、修改）
 * - A/B测试框架支持
 * - 自动化模型迭代优化
 */

import { logger } from '@/utils/safeLogger'
import { type ExpertSuggestionV2 } from '../services/professionalIntelligenceEngine'

export interface FeedbackRecord {
  id: string
  suggestionId: string
  action: 'impression' | 'click' | 'adopt' | 'dismiss' | 'modify' | 'report'
  timestamp: number
  context: {
    inputText: string
    position: number
    visibleSuggestions: number
  }
  metadata: {
    sessionDuration: number
    deviceType: string
    userAgent: string
    reportReason?: string
  }
}

export interface QualityScore {
  overallScore: number
  relevanceScore: number
  noveltyScore: number
  actionabilityScore: number
  evidenceStrength: number
  userSatisfactionPredicted: number
  breakdown: {
    terminologyPrecision: number
    domainCoverage: number
    solutionCompleteness: number
    riskAwareness: number
    referenceQuality: number
  }
}

// ============ 用户行为追踪器 ============

export class FeedbackTracker {
  private feedbackRecords: Map<string, FeedbackRecord[]>
  private sessionStats: {
    totalImpressions: number
    totalClicks: number
    totalAdoptions: number
    totalDismissals: number
    averageDwellTime: number
  }
  private maxRecordsPerSession: number

  constructor(maxRecordsPerSession = 1000) {
    this.feedbackRecords = new Map()
    this.sessionStats = {
      totalImpressions: 0,
      totalClicks: 0,
      totalAdoptions: 0,
      totalDismissals: 0,
      averageDwellTime: 0,
    }
    this.maxRecordsPerSession = maxRecordsPerSession

    this.initializeFromStorage()
  }

  recordImpression(suggestionId: string, inputText: string, position: number, visibleCount: number): void {
    this.sessionStats.totalImpressions++

    this.addRecord(suggestionId, 'click', { // impression作为弱点击信号
      inputText,
      position,
      visibleSuggestions: visibleCount,
    })
  }

  recordClick(suggestionId: string, inputText: string, position: number, visibleCount: number): void {
    this.sessionStats.totalClicks++

    this.addRecord(suggestionId, 'click', {
      inputText,
      position,
      visibleSuggestions: visibleCount,
    })
  }

  recordAdoption(suggestionId: string, inputText: string, position: number): void {
    this.sessionStats.totalAdoptions++

    this.addRecord(suggestionId, 'adopt', {
      inputText,
      position,
      visibleSuggestions: 0,
    })
  }

  recordDismissal(suggestionId: string, inputText: string, position: number, visibleCount: number): void {
    this.sessionStats.totalDismissals++

    this.addRecord(suggestionId, 'dismiss', {
      inputText,
      position,
      visibleSuggestions: visibleCount,
    })
  }

  recordModification(suggestionId: string, originalText: string, _modifiedText: string): void {
    void _modifiedText;
    this.addRecord(suggestionId, 'modify', {
      inputText: originalText,
      position: 0,
      visibleSuggestions: 0,
    })
  }

  recordReport(suggestionId: string, inputText: string, reason: string): void {
    const record = this.addRecord(suggestionId, 'report', {
      inputText,
      position: 0,
      visibleSuggestions: 0,
    })

    if (record) {
      record.metadata.reportReason = reason;
    }
  }

  getFeedbackForSuggestion(suggestionId: string): FeedbackRecord[] {
    return this.feedbackRecords.get(suggestionId) || []
  }

  getSessionStats() {
    return { ...this.sessionStats }
  }

  calculateCTR(): number {
    return this.sessionStats.totalImpressions > 0
      ? this.sessionStats.totalClicks / this.sessionStats.totalImpressions
      : 0
  }

  calculateAdoptionRate(): number {
    return this.sessionStats.totalClicks > 0
      ? this.sessionStats.totalAdoptions / this.sessionStats.totalClicks
      : 0
  }

  exportFeedbackData(): FeedbackRecord[] {
    const allRecords: FeedbackRecord[] = []
    this.feedbackRecords.forEach(records => {
      allRecords.push(...records)
    })
    return allRecords.sort((a, b) => b.timestamp - a.timestamp)
  }

  clearSessionData(): void {
    this.feedbackRecords.clear()
    this.sessionStats = {
      totalImpressions: 0,
      totalClicks: 0,
      totalAdoptions: 0,
      totalDismissals: 0,
      averageDwellTime: 0,
    }
  }

  private addRecord(
    suggestionId: string,
    action: FeedbackRecord['action'],
    context: FeedbackRecord['context'],
  ): FeedbackRecord | null {
    if (this.getTotalRecordCount() >= this.maxRecordsPerSession) {
      logger.warn('[FeedbackTracker] 达到最大记录数限制，丢弃新记录')
      return null
    }

    const record: FeedbackRecord = {
      id: `fb-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`,
      suggestionId,
      action,
      timestamp: Date.now(),
      context,
      metadata: {
        sessionDuration: window.performance.now(),
        deviceType: this.detectDeviceType(),
        userAgent: navigator.userAgent.substring(0, 100),
      },
    }

    const existing = this.feedbackRecords.get(suggestionId) || []
    existing.push(record)
    this.feedbackRecords.set(suggestionId, existing)

    return record
  }

  private getTotalRecordCount(): number {
    let count = 0
    this.feedbackRecords.forEach(records => {
      count += records.length
    })
    return count
  }

  private detectDeviceType(): string {
    const ua = navigator.userAgent
    if (/Mobile|Android|iPhone/i.test(ua)) return 'mobile'
    if (/Tablet|iPad/i.test(ua)) return 'tablet'
    return 'desktop'
  }

  private initializeFromStorage(): void {
    try {
      const stored = localStorage.getItem('pie_v4_feedback_session')
      if (stored) {
        const data = JSON.parse(stored)
        this.sessionStats = data.stats || this.sessionStats
      }
    } catch (error) {
      logger.warn('[FeedbackTracker] 初始化失败:', error)
    }
  }
}

// ============ 质量评分引擎 ============

export class QualityScorer {
  private feedbackTracker: FeedbackTracker
  private weights: {
    relevance: number
    novelty: number
    actionability: number
    evidenceStrength: number
    userSatisfaction: number
  }

  constructor(feedbackTracker: FeedbackTracker) {
    this.feedbackTracker = feedbackTracker

    this.weights = {
      relevance: 0.30,       // 相关性权重最高
      novelty: 0.15,         // 新颖性
      actionability: 0.25,   // 可操作性
      evidenceStrength: 0.20, // 证据强度
      userSatisfaction: 0.10,  // 用户满意度预测
    }
  }

  calculateQualityScore(
    suggestion: ExpertSuggestionV2,
    userInput: string,
    recognizedTerms: string[],
  ): QualityScore {
    const relevanceScore = this.calculateRelevanceScore(suggestion, userInput, recognizedTerms)
    const noveltyScore = this.calculateNoveltyScore(suggestion, userInput)
    const actionabilityScore = this.calculateActionabilityScore(suggestion)
    const evidenceStrength = this.calculateEvidenceStrength(suggestion)
    const userSatisfactionPredicted = this.predictUserSatisfaction(suggestion.id)

    const overallScore =
      relevanceScore * this.weights.relevance +
      noveltyScore * this.weights.novelty +
      actionabilityScore * this.weights.actionability +
      evidenceStrength * this.weights.evidenceStrength +
      userSatisfactionPredicted * this.weights.userSatisfaction

    return {
      overallScore: Math.round(overallScore),
      relevanceScore: Math.round(relevanceScore),
      noveltyScore: Math.round(noveltyScore),
      actionabilityScore: Math.round(actionabilityScore),
      evidenceStrength: Math.round(evidenceStrength),
      userSatisfactionPredicted: Math.round(userSatisfactionPredicted * 100),
      breakdown: {
        terminologyPrecision: this.evaluateTerminologyPrecision(suggestion, recognizedTerms),
        domainCoverage: this.evaluateDomainCoverage(suggestion, recognizedTerms),
        solutionCompleteness: this.evaluateSolutionCompleteness(suggestion),
        riskAwareness: this.evaluateRiskAwareness(suggestion),
        referenceQuality: this.evaluateReferenceQuality(suggestion),
      },
    }
  }

  private calculateRelevanceScore(
    suggestion: ExpertSuggestionV2,
    userInput: string,
    recognizedTerms: string[],
  ): number {
    let score = 50 // 基础分

    // 标题匹配度
    const titleLower = suggestion.title.toLowerCase()
    const inputLower = userInput.toLowerCase()

    recognizedTerms.forEach(term => {
      if (titleLower.includes(term.toLowerCase())) score += 10
      if (inputLower.includes(term.toLowerCase())) score += 5
    })

    // 领域匹配
    if (suggestion.metadata.domain && recognizedTerms.length > 0) {
      score += 15
    }

    return Math.min(score, 100)
  }

  private calculateNoveltyScore(suggestion: ExpertSuggestionV2, _userInput: string): number {
    void _userInput;
    const feedbackRecords = this.feedbackTracker.getFeedbackForSuggestion(suggestion.id)

    if (feedbackRecords.length === 0) return 80 // 新建议默认高分

    const recentAdoptions = feedbackRecords.filter(r =>
      r.action === 'adopt' &&
      Date.now() - r.timestamp < 7 * 24 * 60 * 60 * 1000, // 最近7天
    ).length

    if (recentAdoptions > 10) return 40 // 过度使用降分
    if (recentAdoptions > 5) return 60
    return 75
  }

  private calculateActionabilityScore(suggestion: ExpertSuggestionV2): number {
    if (!suggestion.content.actionableSteps || suggestion.content.actionableSteps.length === 0) {
      return 20
    }

    let score = 40

    suggestion.content.actionableSteps.forEach(step => {
      if (step.action && step.rationale && step.expectedOutcome) score += 10
      if (step.resources && step.resources.length > 0) score += 5
      if (step.timeEstimate) score += 3
    })

    return Math.min(score, 100)
  }

  private calculateEvidenceStrength(suggestion: ExpertSuggestionV2): number {
    if (!suggestion.content.references || suggestion.content.references.length === 0) {
      return 30
    }

    let score = 30

    suggestion.content.references.forEach(ref => {
      switch (ref.type) {
        case 'clinical_trial':
          score += 20
          break
        case 'meta_analysis':
          score += 18
          break
        case 'guideline':
          score += 15
          break
        case 'industry_report':
          score += 10
          break
        case 'patent':
          score += 8
          break
      }

      if (ref.year && ref.year >= 2020) score += 5 // 近年文献加分
      if (ref.doi) score += 3 // 有DOI加分
    })

    return Math.min(score, 100)
  }

  private predictUserSatisfaction(suggestionId: string): number {
    const records = this.feedbackTracker.getFeedbackForSuggestion(suggestionId)

    if (records.length === 0) return 0.7 // 默认70%满意度预测

    const adoptions = records.filter(r => r.action === 'adopt').length
    const clicks = records.filter(r => r.action === 'click').length
    const dismissals = records.filter(r => r.action === 'dismiss').length

    const totalInteractions = adoptions + clicks + dismissals
    if (totalInteractions === 0) return 0.7

    const satisfactionRate = (adoptions * 1.0 + clicks * 0.6 - dismissals * 0.3) / totalInteractions
    return Math.max(0, Math.min(1, satisfactionRate))
  }

  private evaluateTerminologyPrecision(suggestion: ExpertSuggestionV2, recognizedTerms: string[]): number {
    const titleTerms = suggestion.title.match(/[\u4e00-\u9fa5]{2,}/g) || []
    const matchedTerms = titleTerms.filter(term =>
      recognizedTerms.some(rt => term.includes(rt) || rt.includes(term)),
    )

    return recognizedTerms.length > 0
      ? (matchedTerms.length / recognizedTerms.length) * 100
      : 50
  }

  private evaluateDomainCoverage(suggestion: ExpertSuggestionV2, recognizedTerms: string[]): number {
    const domains = new Set(recognizedTerms.map(t => {
      // 简化的域名映射
      if (['黄芪', '复合多肽', '人参'].includes(t)) return 'functional_ingredients'
      if (['降三高', '免疫调节'].includes(t)) return 'health_claims'
      if (['固体饮料'].includes(t)) return 'product_forms'
      return 'general'
    }))

    return domains.has(suggestion.metadata.domain as 'functional_ingredients' | 'health_claims' | 'product_forms' | 'general') ? 90 : 60
  }

  private evaluateSolutionCompleteness(suggestion: ExpertSuggestionV2): number {
    const requiredSections = [
      suggestion.content.executiveSummary,
      suggestion.content.detailedAnalysis?.length > 0,
      suggestion.content.actionableSteps?.length > 0,
      suggestion.content.technicalSpecifications?.length > 0,
      suggestion.content.riskAssessment?.length > 0,
      suggestion.content.references?.length > 0,
    ]

    const completedSections = requiredSections.filter(Boolean).length
    return (completedSections / requiredSections.length) * 100
  }

  private evaluateRiskAwareness(suggestion: ExpertSuggestionV2): number {
    if (!suggestion.content.riskAssessment || suggestion.content.riskAssessment.length === 0) {
      return 20
    }

    let score = 40
    suggestion.content.riskAssessment.forEach(risk => {
      if (risk.mitigation && risk.monitoring) score += 20
      if (risk.probability !== undefined && risk.impact !== undefined) score += 10
    })

    return Math.min(score, 100)
  }

  private evaluateReferenceQuality(suggestion: ExpertSuggestionV2): number {
    if (!suggestion.content.references || suggestion.content.references.length === 0) {
      return 0
    }

    const highQualityTypes = ['clinical_trial', 'meta_analysis', 'guideline']
    const highQualityCount = suggestion.content.references.filter(ref =>
      highQualityTypes.includes(ref.type),
    ).length

    return (highQualityCount / suggestion.content.references.length) * 100
  }

  updateWeights(newWeights: Partial<typeof this.weights>): void {
    Object.assign(this.weights, newWeights)
  }
}

// ============ A/B测试管理器 ============

export interface ABTestVariant {
  id: string
  name: string
  description: string
  config: Record<string, any>
  trafficAllocation: number // 0-1 (占比)
}

export interface ABTestExperiment {
  id: string
  name: string
  hypothesis: string
  startDate: string
  endDate?: string
  status: 'draft' | 'running' | 'completed' | 'paused'
  variants: ABTestVariant[]
  primaryMetric: string
  secondaryMetrics: string[]
  targetSampleSize: number
  currentSampleSize: number
  results?: {
    variantId: string
    metricValue: number
    confidenceInterval: [number, number]
    isWinner: boolean
  }[]
}

export class ABTestManager {
  private experiments: Map<string, ABTestExperiment>
  private userAssignments: Map<string, string> // userId → variantId

  constructor() {
    this.experiments = new Map()
    this.userAssignments = new Map()

    this.loadFromStorage()
  }

  createExperiment(config: {
    name: string
    hypothesis: string
    variants: { name: string; description: string; config: Record<string, any>; trafficAllocation?: number }[]
    primaryMetric: string
    secondaryMetrics?: string[]
    targetSampleSize?: number
  }): ABTestExperiment {
    const experiment: ABTestExperiment = {
      id: `ab-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`,
      name: config.name,
      hypothesis: config.hypothesis,
      startDate: new Date().toISOString(),
      status: 'draft',
      variants: config.variants.map((v, index) => ({
        id: `variant-${index}`,
        name: v.name,
        description: v.description,
        config: v.config,
        trafficAllocation: v.trafficAllocation || (1 / config.variants.length),
      })),
      primaryMetric: config.primaryMetric,
      secondaryMetrics: config.secondaryMetrics || [],
      targetSampleSize: config.targetSampleSize || 1000,
      currentSampleSize: 0,
    }

    this.experiments.set(experiment.id, experiment)
    this.saveToStorage()

    return experiment
  }

  startExperiment(experimentId: string): boolean {
    const experiment = this.experiments.get(experimentId)
    if (experiment?.status !== 'draft') return false

    experiment.status = 'running'
    this.saveToStorage()

    logger.log(`[ABTestManager] 🧪 实验 "${experiment.name}" 已启动`)
    return true
  }

  assignVariant(experimentId: string, userId?: string): ABTestVariant | null {
    const experiment = this.experiments.get(experimentId)
    if (experiment?.status !== 'running') return null

    // 检查是否已有分配
    const cacheKey = `${experimentId}_${userId || 'anonymous'}`
    const cachedAssignment = this.userAssignments.get(cacheKey)
    if (cachedAssignment) {
      return experiment.variants.find(v => v.id === cachedAssignment) || null
    }

    // 基于流量分配随机选择
    const random = Math.random()
    let cumulative = 0
    for (const variant of experiment.variants) {
      cumulative += variant.trafficAllocation
      if (random <= cumulative) {
        this.userAssignments.set(cacheKey, variant.id)
        experiment.currentSampleSize++

        logger.log(`[ABTestManager] 👤 用户分配到变体: ${variant.name} (${(variant.trafficAllocation * 100).toFixed(1)}%)`)
        return variant
      }
    }

    return experiment.variants[experiment.variants.length - 1] || null
  }

  recordMetric(experimentId: string, variantId: string, _metricName: string, value: number): void {
    const experiment = this.experiments.get(experimentId)
    if (!experiment) return

    if (!experiment.results) {
      experiment.results = []
    }

    let result = experiment.results.find(r => r.variantId === variantId)
    if (!result) {
      result = {
        variantId,
        metricValue: 0,
        confidenceInterval: [0, 0],
        isWinner: false,
      }
      experiment.results.push(result)
    }

    // 简化的增量更新（实际应使用统计库）
    result.metricValue = (result.metricValue * (experiment.currentSampleSize - 1) + value) / experiment.currentSampleSize

    this.checkExperimentCompletion(experiment)
    this.saveToStorage()
  }

  getExperimentResults(experimentId: string): ABTestExperiment | null {
    return this.experiments.get(experimentId) || null
  }

  getAllExperiments(): ABTestExperiment[] {
    return Array.from(this.experiments.values())
  }

  private checkExperimentCompletion(experiment: ABTestExperiment): void {
    if (experiment.currentSampleSize >= experiment.targetSampleSize) {
      experiment.status = 'completed'

      if (experiment.results) {
        const sortedResults = [...experiment.results].sort((a, b) => b.metricValue - a.metricValue)
        if (sortedResults.length > 0) {
          sortedResults[0].isWinner = true
        }
      }

      logger.log(`[ABTestManager] ✅ 实验 "${experiment.name}" 已完成!`)
      logger.log(`[ABTestManager] 结果:`, experiment.results?.map(r => ({
        变体: r.variantId,
        指标值: r.metricValue.toFixed(4),
        是否获胜: r.isWinner,
      })))
    }
  }

  private saveToStorage(): void {
    try {
      const data = {
        experiments: Array.from(this.experiments.entries()),
        assignments: Array.from(this.userAssignments.entries()),
      }
      localStorage.setItem('pie_v4_abtests', JSON.stringify(data))
    } catch (error) {
      logger.warn('[ABTestManager] 保存失败:', error)
    }
  }

  private loadFromStorage(): void {
    try {
      const stored = localStorage.getItem('pie_v4_abtests')
      if (stored) {
        const data = JSON.parse(stored)
        this.experiments = new Map(data.experiments)
        this.userAssignments = new Map(data.assignments)
      }
    } catch (error) {
      logger.warn('[ABTestManager] 加载失败:', error)
    }
  }
}

// ============ 导出实例工厂 ============

export function createFeedbackSystem() {
  const tracker = new FeedbackTracker()
  const scorer = new QualityScorer(tracker)
  const abTestManager = new ABTestManager()

  return {
    tracker,
    scorer,
    abTestManager,
  }
}

/**
 * FormulaIntelligenceService — 配方智能对话服务
 *
 * 将 FormulaDesignEngine 集成到 AI 对话流中：
 * 1. 从用户自然语言输入中提取配方需求
 * 2. 调用 FormulaDesignEngine 生成配方
 * 3. 将结果转换为结构化内容块
 * 4. 支持多轮配方优化对话
 *
 * @version 1.0.0
 */

import { FormulaDesignEngine, formulaDesignEngine } from './formulaDesignEngine'
import type { FormulaCandidate, FormulaDesignRequest } from './formulaDesignEngine'
import { FormulaDialogueManager } from './dialogue/FormulaDialogueManager'
import { knowledgeGraph } from './knowledge/FormulaKnowledgeGraph'
import { logger } from '@/utils/safeLogger'

/* ================================================================== */
/*  类型定义                                                            */
/* ================================================================== */

export interface DialogueState {
  sessionId: string
  currentFormula: FormulaCandidate | null
  optimizationHistory: FormulaCandidate[]
  userPreferences: {
    targetEffects: string[]
    constraints: FormulaDesignRequest['constraints']
    userProfile: FormulaDesignRequest['userProfile']
  }
  dialogueRound: number
  lastQuery: string
}

/** 意图类型 */
export type IntentType =
  | 'formula_design'      // 设计新配方
  | 'formula_optimize'    // 优化现有配方
  | 'formula_analyze'     // 分析配方
  | 'ingredient_query'    // 查询成分
  | 'general_chat'        // 普通聊天

/* ================================================================== */
/*  对话式配方设计服务                                                  */
/* ================================================================== */

export class FormulaIntelligenceService {
  private engine: FormulaDesignEngine
  private dialogueSessions: Map<string, DialogueState>
  private dialogueManager: FormulaDialogueManager

  constructor() {
    this.engine = formulaDesignEngine
    this.dialogueSessions = new Map()
    this.dialogueManager = new FormulaDialogueManager()
  }

  /* ================================================================ */
  /*  1. 意图识别                                                      */
  /* ================================================================ */

  /**
   * 识别用户意图
   * 简单 NLP 规则引擎，识别配方相关意图
   */
  detectIntent(query: string): IntentType {
    const q = query.toLowerCase()

    // 配方设计意图
    const designKeywords = [
      '设计', '配方', '做一款', '开发', '研发', '调配',
      '帮我配', '我想做', '定制', 'create', 'formula', 'design',
    ]
    if (designKeywords.some(k => q.includes(k))) return 'formula_design'

    // 优化意图
    const optimizeKeywords = ['优化', '改进', '改善', '提升', '修改', '调整', 'optimize', 'improve']
    if (optimizeKeywords.some(k => q.includes(k))) return 'formula_optimize'

    // 分析意图
    const analyzeKeywords = ['分析', '评估', '评价', '评分', '怎么样', 'analyze', 'evaluate']
    if (analyzeKeywords.some(k => q.includes(k))) return 'formula_analyze'

    // 成分查询
    const ingredientKeywords = ['成分', '原料', '药材', '功效', '作用', 'ingredient', 'effect']
    if (ingredientKeywords.some(k => q.includes(k))) return 'ingredient_query'

    return 'general_chat'
  }

  /* ================================================================ */
  /*  2. 需求提取                                                      */
  /* ================================================================ */

  /**
   * 从自然语言中提取配方设计参数
   */
  extractDesignRequest(query: string, sessionId: string): FormulaDesignRequest {
    const q = query.toLowerCase()
    const session = this.getOrCreateSession(sessionId)
    const effects = this.extractTargetEffects(q)

    // 更新会话偏好
    if (effects.length > 0) {
      session.userPreferences.targetEffects = [
        ...new Set([...session.userPreferences.targetEffects, ...effects]),
      ]
    }

    return {
      targetEffects: effects.length > 0 ? effects : session.userPreferences.targetEffects,
      constraints: session.userPreferences.constraints,
      userProfile: session.userPreferences.userProfile,
    }
  }

  /** 提取目标功效关键词 */
  private extractTargetEffects(query: string): string[] {
    const effectMap: Record<string, string[]> = {
      immunity: ['免疫', '免疫力', '增强免疫', '提高免疫', '抵抗力'],
      anti_fatigue: ['抗疲劳', '疲劳', '乏力', '精力', '提神', '恢复体力'],
      anti_oxidant: ['抗氧化', '延缓衰老', '自由基', '抗氧化'],
      skin_health: ['皮肤', '美容', '护肤', '美白', '胶原蛋白', '养颜'],
      gut_health: ['肠道', '消化', '肠胃', '益生菌', '调理肠胃', '通便'],
      liver_protect: ['护肝', '保肝', '解酒', '肝脏', '肝'],
      cognition: ['健脑', '记忆力', '认知', '大脑', '智力', '专注'],
      joint_health: ['关节', '骨骼', '骨', '关节健康', '补钙'],
      anti_inflammatory: ['抗炎', '消炎', '炎', '舒缓'],
      vision: ['视力', '护眼', '眼', '明目'],
      vitality: ['活力', '强身', '整体健康', '增强体质', '强身健体'],
      metabolism: ['代谢', '减肥', '体重', '血糖', '降糖', '血脂'],
      cardio_protect: ['心血管', '心脏', '血管', '血压', '降血压', '降血脂', '三高', '降三高'],
      anti_aging: ['抗衰老', '衰老', '逆龄', '延年益寿', '长寿'],
      blood_sugar: ['降血糖', '血糖', '糖尿', '降糖'],
      peptide: ['多肽', '肽', '复合肽', '小分子肽', '胶原肽'],
      sleep: ['睡眠', '助眠', '失眠', '安神'],
    }

    const detected: string[] = []
    for (const [effect, keywords] of Object.entries(effectMap)) {
      if (keywords.some(kw => query.includes(kw))) {
        detected.push(effect)
      }
    }

    return detected
  }

  /* ================================================================ */
  /*  3. 对话管理                                                      */
  /* ================================================================ */

  getOrCreateSession(sessionId: string): DialogueState {
    if (!this.dialogueSessions.has(sessionId)) {
      this.dialogueSessions.set(sessionId, {
        sessionId,
        currentFormula: null,
        optimizationHistory: [],
        userPreferences: {
          targetEffects: [],
          constraints: {},
          userProfile: {},
        },
        dialogueRound: 0,
        lastQuery: '',
      })
    }
    return this.dialogueSessions.get(sessionId)!
  }

  /* ================================================================ */
  /*  4. 核心对话处理                                                  */
  /* ================================================================ */

  /**
   * 处理用户对话输入，返回结构化内容块
   */
  processUserInput(query: string, sessionId: string): {
    blocks: Array<{ type: string; data: any }>
    sessionState: DialogueState
  } {
    const session = this.getOrCreateSession(sessionId)
    session.lastQuery = query
    session.dialogueRound++

    const intent = this.detectIntent(query)
    logger.info('[FormulaIntelligence] Detected intent:', { intent, round: session.dialogueRound })

    switch (intent) {
      case 'formula_design':
        return this.handleFormulaDesign(query, session)
      case 'formula_optimize':
        return this.handleFormulaOptimize(query, session)
      case 'formula_analyze':
        return this.handleFormulaAnalyze(query, session)
      case 'ingredient_query':
        return this.handleIngredientQuery(query, session)
      case 'general_chat':
      default:
        return this.handleGeneralChat(query, session)
    }
  }

  private handleFormulaDesign(query: string, session: DialogueState) {
    // v2.0: 使用对话管理器 + 遗传算法 + 知识图谱
    try {
      const blocks = this.dialogueManager.process(query)
      if (blocks.length > 0) {
        return { blocks, sessionState: session }
      }
    } catch {
      // fallback to v1 engine
    }
    const request = this.extractDesignRequest(query, session.sessionId)

    if (request.targetEffects.length === 0) {
      return {
        blocks: [{
          type: 'callout',
          data: {
            variant: 'info',
            title: '配方需求',
            content: '请告诉我您想要的配方功效方向，例如：\n• "我想设计一款增强免疫力的配方"\n• "帮我做一款抗疲劳的固体饮料"\n• "设计一款美容护肤的胶原蛋白肽产品"',
          },
        }],
        sessionState: session,
      }
    }

    // 生成配方
    const formula = this.engine.generateFormula(request)
    session.currentFormula = formula
    session.optimizationHistory.push(formula)

    // 转为结构化内容块
    const blocks = this.engine.toStructuredBlocks(formula)
    // v2.0: 添加知识图谱分析
    const ingIds = formula.ingredients.map(i => i.profile.id)
    const knowledgeStats = knowledgeGraph.getStats()
    if (knowledgeStats.ingredients > 0) {
      const compatMatrix = this.engine.analyzeCompatibility(ingIds)
      const synergyCount = compatMatrix.filter(m => m.interaction === 'synergy').length
      const warningCount = compatMatrix.filter(m => m.interaction === 'antagonism').length
      // Insert compatibility metric
      blocks.splice(2, 0, {
        type: 'metrics',
        data: {
          title: '配伍分析',
          items: [
            { label: '协同组合', value: synergyCount, unit: '项', trend: 'up' },
            { label: '注意事项', value: warningCount, unit: '项', trend: warningCount > 0 ? 'down' : 'stable' },
          ],
        },
      })
    }

    // 添加对话引导
    blocks.push({
      type: 'callout',
      data: {
        variant: 'info',
        title: '下一步操作',
        content: '您可以通过以下指令继续优化：\n• "优化这个配方" — 自动迭代优化\n• "增加XXX成分" — 添加指定成分\n• "调整用量" — 微调各成分比例\n• "分析安全性" — 详细安全评估',
      },
    })

    return { blocks, sessionState: session }
  }

  private handleFormulaOptimize(query: string, session: DialogueState) {
    if (!session.currentFormula) {
      return this.handleFormulaDesign(query, session)
    }

    const optimized = this.engine.optimizeFormula(session.currentFormula, 3)
    const best = optimized[0]
    session.currentFormula = best
    session.optimizationHistory.push(best)

    const blocks = this.engine.toStructuredBlocks(best)

    // 添加优化对比
    if (optimized.length > 1) {
      blocks.splice(2, 0, {
        type: 'data-table',
        data: {
          title: 'Pareto 优化对比',
          columns: [
            { key: 'name', label: '配方版本' },
            { key: 'efficacy', label: '功效', type: 'percentage', align: 'center' },
            { key: 'safety', label: '安全', type: 'percentage', align: 'center' },
            { key: 'overall', label: '综合', type: 'percentage', align: 'center' },
            { key: 'change', label: '变化' },
          ],
          rows: optimized.slice(0, 4).map((f, i) => ({
            name: i === 0 ? '优化版 ✓' : `备选 ${i}`,
            efficacy: f.scores.efficacy,
            safety: f.scores.safety,
            overall: f.overallScore,
            change: i === 0 ? '最优解' : `综合+${(f.overallScore - optimized[0].overallScore > 0.01 ? '+' : '')}${Math.round((f.overallScore - optimized[0].overallScore) * 100)}%`,
          })),
          summary: `经过 ${optimized.length} 轮 Pareto 优化，综合评分提升 ${Math.round((best.overallScore - session.optimizationHistory[0].overallScore) * 100)}%`,
        },
      })
    }

    blocks.push({
      type: 'callout',
      data: {
        variant: 'success',
        title: '优化完成',
        content: `配方已迭代优化至第 ${session.optimizationHistory.length} 版。您可以继续调整或确认此方案。`,
      },
    })

    return { blocks, sessionState: session }
  }

  private handleFormulaAnalyze(query: string, session: DialogueState) {
    if (!session.currentFormula) {
      return {
        blocks: [{
          type: 'callout',
          data: {
            variant: 'warning',
            title: '暂无配方',
            content: '请先设计一个配方，我可以为您详细分析其配伍合理性、安全性和功效特征。',
          },
        }],
        sessionState: session,
      }
    }

    const formula = session.currentFormula
    const blocks: Array<{ type: string; data: any }> = []

    blocks.push({
      type: 'header',
      data: {
        title: `🔬 ${formula.name} — 深度分析报告`,
        level: 1,
        metadata: [
          { label: '分析时间', value: new Date().toLocaleString('zh-CN') },
          { label: '综合评分', value: `${Math.round(formula.overallScore * 100)}分` },
        ],
      },
    })

    // 多维雷达数据
    blocks.push({
      type: 'chart',
      data: {
        chartType: 'radar',
        title: '五维能力雷达图',
        data: {
          synergy: formula.scores.efficacy,
          taste: formula.scores.taste,
          stability: formula.scores.stability,
          safety: formula.scores.safety,
        },
      },
    })

    // 安全性详细分析
    const safetyIssues = formula.compatibilityMatrix.filter(
      m => m.interaction === 'antagonism' || m.interaction === 'toxicity' || m.score < 0
    )
    if (safetyIssues.length > 0) {
      blocks.push({
        type: 'callout',
        data: {
          variant: 'warning',
          title: '安全提示',
          content: `检测到 ${safetyIssues.length} 项配伍注意点`,
          details: safetyIssues.map(i => i.description),
        },
      })
    }

    blocks.push({
      type: 'callout',
      data: {
        variant: 'success',
        title: '分析结论',
        content: `该配方${formula.scores.safety >= 0.7 ? '安全性良好，' : '需关注安全性。'}${formula.scores.efficacy >= 0.7 ? '功效预期显著。' : '功效有待提升。'}综合评估：${formula.overallScore >= 0.7 ? '推荐使用' : '建议进一步优化'}。`,
        details: [
          `君药：${formula.ingredients.find(i => i.role === 'jun')?.profile.name || '无'}`,
          `配伍协同项：${formula.compatibilityMatrix.filter(m => m.interaction === 'synergy').length} 项`,
          `建议周期：4-8 周`,
        ],
      },
    })

    return { blocks, sessionState: session }
  }

  private handleIngredientQuery(query: string, session: DialogueState) {
    const q = query.toLowerCase()
    // 提取成分名
    const allIngredients = this.engine.getAllIngredients()
    const matchedIngredient = allIngredients.find(ing => q.includes(ing.name))

    if (matchedIngredient) {
      return {
        blocks: [{
          type: 'header',
          data: {
            title: `🌿 ${matchedIngredient.name}`,
            description: matchedIngredient.latinName || '',
            level: 1,
            metadata: [
              { label: '分类', value: matchedIngredient.category },
              { label: '四气', value: matchedIngredient.properties.nature || '—' },
              { label: '五味', value: matchedIngredient.properties.flavor?.join('、') || '—' },
              { label: '归经', value: matchedIngredient.properties.meridians?.join('、') || '—' },
            ],
          },
        }, {
          type: 'metrics',
          data: {
            items: Object.entries(matchedIngredient.efficacyVector).map(([key, val]) => ({
              label: this.getEffectLabel(key),
              value: Math.round(val * 100),
              unit: '分',
            })),
          },
        }, {
          type: 'data-table',
          data: {
            title: '用量参考',
            columns: [
              { key: 'item', label: '项目' },
              { key: 'value', label: '数值' },
            ],
            rows: [
              { item: '推荐用量', value: `${matchedIngredient.dosageRange[0]} - ${matchedIngredient.dosageRange[1]} g` },
              { item: '安全上限', value: `${matchedIngredient.safetyLimit} g` },
            ],
          },
        }, {
          type: 'callout',
          data: {
            variant: 'info',
            title: '参考文献',
            content: matchedIngredient.references.join('；'),
          },
        }],
        sessionState: session,
      }
    }

    // 展示所有成分供选择
    return {
      blocks: [{
        type: 'header',
        data: { title: '🌿 成分知识库', description: `${allIngredients.length} 种可用成分`, level: 2 },
      }, {
        type: 'data-table',
        data: {
          columns: [
            { key: 'name', label: '名称' },
            { key: 'nature', label: '四气', type: 'tag' },
            { key: 'flavor', label: '五味' },
            { key: 'category', label: '分类', type: 'tag' },
            { key: 'dosage', label: '用量(g)', type: 'text' },
          ],
          rows: allIngredients.map(ing => ({
            name: ing.name,
            nature: ing.properties.nature || '—',
            flavor: ing.properties.flavor?.join('、') || '—',
            category: ing.category,
            dosage: `${ing.dosageRange[0]}-${ing.dosageRange[1]}`,
          })),
        },
      }, {
        type: 'callout',
        data: {
          variant: 'info',
          title: '提示',
          content: '输入具体成分名称（如"黄芪"）可查看详细档案及参考文献',
        },
      }],
      sessionState: session,
    }
  }

  private handleGeneralChat(_query: string, session: DialogueState) {
    return {
      blocks: [{
        type: 'callout',
        data: {
          variant: 'info',
          title: 'AI 配方设计助手',
          content: '我可以帮您设计专业的食品配方。试试这些：\n\n• "设计一款增强免疫力的配方"\n• "做一款抗疲劳的固体饮料"\n• "咨询黄芪的功效和用量"\n• "展示所有可用成分"',
        },
      }],
      sessionState: session,
    }
  }

  /** 重置对话会话 */
  resetSession(sessionId: string): void {
    this.dialogueSessions.delete(sessionId)
  }

  private getEffectLabel(key: string): string {
    const labels: Record<string, string> = {
      immunity: '免疫增强', anti_fatigue: '抗疲劳', anti_oxidant: '抗氧化',
      anti_aging: '抗衰老', skin_health: '皮肤健康', gut_health: '肠道健康',
      cognition: '健脑益智', liver_protect: '保肝护肝', vision: '明目',
      joint_health: '关节健康', anti_inflammatory: '抗炎', cardio_protect: '心血管',
      metabolism: '代谢调节', adaptogen: '抗应激', vitality: '活力提升',
      blood_nourish: '补血', detoxify: '解毒', harmonize: '调和诸药',
      digestion: '助消化', prebiotic: '益生元', wound_healing: '伤口愈合',
      growth: '促进生长', muscle: '肌肉健康',
	      bone_health: '骨骼健康',
    }
    return labels[key] || key
  }
}

